49	function startOfUtcDay(now = new Date()): Date {
50	  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
51	}
52	
53	/** Current minute-of-day in a timezone (falls back to UTC on a bad tz). */
54	function minutesInTz(now: Date, tz: string): number {
55	  try {
56	    const parts = new Intl.DateTimeFormat("en-US", {
57	      timeZone: tz || "UTC",
58	      hour: "2-digit",
59	      minute: "2-digit",
60	      hour12: false,
61	    }).formatToParts(now);
62	    const h = Number(parts.find((p) => p.type === "hour")?.value ?? "0") % 24;
63	    const m = Number(parts.find((p) => p.type === "minute")?.value ?? "0");
64	    return h * 60 + m;
65	  } catch {
66	    return now.getUTCHours() * 60 + now.getUTCMinutes();
67	  }
68	}
69	
70	function withinSendWindow(
71	  c: { sendWindowStart: number | null; sendWindowEnd: number | null; timezone: string },
72	  now: Date,
73	): boolean {
74	  if (c.sendWindowStart == null || c.sendWindowEnd == null) return true;
75	  const cur = minutesInTz(now, c.timezone || "UTC");
76	  const s = c.sendWindowStart;
77	  const e = c.sendWindowEnd;
78	  return s <= e ? cur >= s && cur < e : cur >= s || cur < e; // handle wrap past midnight
79	}
80	
81	type CampaignForSend = {
82	  id: string;
83	  brandId: string;
84	  listId: string;
85	  launchedAt: Date | null;
86	  sendWindowStart: number | null;
87	  sendWindowEnd: number | null;
88	  timezone: string;
89	};
90	
91	/**
92	 * Ensure a ColdSend row exists for every (contact, step) in a campaign, with the
93	 * scheduledFor honouring cumulative step delays from the launch anchor. Idempotent
94	 * — the unique(campaignId, contactId, stepId) + skipDuplicates makes re-runs free.
95	 */
96	async function scheduleCampaignSends(campaign: CampaignForSend): Promise<void> {
97	  const steps = await db.sequenceStep.findMany({
98	    where: { campaignId: campaign.id },
99	    orderBy: { stepOrder: "asc" },
100	    select: { id: true, delayDays: true },
101	  });
102	  if (steps.length === 0) return;
103	
104	  const base = campaign.launchedAt ?? new Date();
105	  // Cumulative offset (days) at each step.
106	  let cumulative = 0;
107	  const stepSchedule = steps.map((s) => {
108	    cumulative += Math.max(0, s.delayDays);
109	    return { stepId: s.id, scheduledFor: new Date(base.getTime() + cumulative * 86_400_000) };
110	  });
111	
112	  const members = await db.emailListMember.findMany({
113	    where: { listId: campaign.listId },
114	    select: { contactId: true },
115	  });
116	  if (members.length === 0) return;
117	
118	  const rows: { campaignId: string; contactId: string; stepId: string; scheduledFor: Date }[] = [];
119	  for (const m of members) {
120	    for (const s of stepSchedule) {
121	      rows.push({ campaignId: campaign.id, contactId: m.contactId, stepId: s.stepId, scheduledFor: s.scheduledFor });
122	    }
123	  }
124	  // createMany + skipDuplicates: never double-queues a message across sweeps.
125	  await db.coldSend.createMany({ data: rows, skipDuplicates: true });
126	}
127	
128	/**
129	 * Process due sends for one eligible campaign. Returns the number actually sent so
130	 * the caller can respect the per-sweep budget across campaigns.
131	 */
132	async function processDueSends(
133	  campaign: CampaignForSend,
134	  identity: SendIdentity,
135	  ctx: {
136	    now: Date;
137	    transport: MailTransport;
138	    ceiling: number;
139	    warmupEnabled: boolean;
140	    footerDisclosure: string;
141	    budget: number;
142	  },
143	): Promise<number> {
144	  if (ctx.budget <= 0) return 0;
145	  if (!withinSendWindow(campaign, ctx.now)) return 0;
146	
147	  // Per-inbox daily cap (warmup-aware). Counts REAL sends today for the brand.
148	  const brand = await db.brand.findUnique({
149	    where: { id: campaign.brandId },
150	    select: { warmupStartedAt: true, dailySendCap: true },
151	  });
152	  const cap = effectiveDailyCap({
153	    warmupStartedAt: brand?.warmupStartedAt ?? null,
154	    ceiling: brand?.dailySendCap ?? ctx.ceiling,
155	    warmupEnabled: ctx.warmupEnabled,
156	    now: ctx.now,
157	  });
158	  let sentToday = await db.coldSend.count({
159	    where: { campaign: { brandId: campaign.brandId }, sentAt: { gte: startOfUtcDay(ctx.now) } },
160	  });
161	  if (sentToday >= cap) return 0;
162	
163	  // Suppression rows for this brand, loaded once (GLOBAL + this brand's BRAND tier).
164	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
165	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
166	    select: { email: true, domain: true, scope: true, brandId: true },
167	  });
168	
169	  const due = await db.coldSend.findMany({
170	    where: {
171	      campaignId: campaign.id,
172	      status: "QUEUED",
173	      stepId: { not: null },
174	      scheduledFor: { lte: ctx.now },
175	    },
176	    orderBy: { scheduledFor: "asc" },
177	    take: ctx.budget,
178	    include: {
179	      contact: { select: { id: true, email: true, fullName: true, title: true, business: { select: { name: true } } } },
180	      step: { select: { subject: true, bodyMarkdown: true } },
181	    },
182	  });
183	
184	  let sent = 0;
185	  for (const s of due) {
186	    if (!s.step || !s.contact) continue;
187	
188	    // GUARDRAIL #4 — re-check suppression immediately before the send.
189	    if (isSuppressed(s.contact.email, campaign.brandId, suppressions)) {
190	      await db.coldSend.update({ where: { id: s.id }, data: { status: "SUPPRESSED" } });
191	      continue;
192	    }
193	
194	    // Per-inbox daily cap: stop (leave the rest QUEUED for the next window/day).
195	    if (sentToday >= cap) break;
196	
197	    const token = openTrackingToken(s.id);
198	    const msg = buildMessage({
199	      identity,
200	      step: s.step,
201	      contact: s.contact,
202	      sendId: s.id,
203	      footerDisclosure: ctx.footerDisclosure,
204	      track: true,
205	    });
206	
207	    try {
208	      const res = await ctx.transport.send(msg);
209	      await db.coldSend.update({
210	        where: { id: s.id },
211	        data: { status: "SENT", sentAt: new Date(), messageId: res.messageId ?? null, trackingToken: token, error: null },
212	      });
213	      await db.emailEvent.create({ data: { sendId: s.id, type: "SENT" } });
214	      sentToday++;
215	      sent++;
216	    } catch (err) {
217	      const error = String((err as Error)?.message ?? err).slice(0, 500);
218	      await db.coldSend.update({ where: { id: s.id }, data: { status: "FAILED", error, trackingToken: token } });
219	      await db.emailEvent.create({ data: { sendId: s.id, type: "FAILED", meta: error } });
220	      await logEvent("error", "coldemail.send.fail", { campaignId: campaign.id, sendId: s.id, error });
221	    }
222	
223	    await sleep(jitter());
224	  }
225	  return sent;
226	}
227	
228	/** Mark a campaign DONE once nothing is left QUEUED (all sends terminal). */
229	async function maybeCompleteCampaign(campaignId: string): Promise<void> {
230	  const remaining = await db.coldSend.count({ where: { campaignId, status: "QUEUED" } });
231	  if (remaining > 0) return;
232	  const any = await db.coldSend.count({ where: { campaignId } });
233	  if (any === 0) return; // nothing was ever scheduled — leave it SENDING
234	  await db.coldCampaign.update({ where: { id: campaignId }, data: { status: "DONE" } });
235	}
236	
237	/**
238	 * The send sweep. GATED by `cold_email_sending_enabled` — the single line that
239	 * keeps everything below inert until a human enables sending on prod.
240	 */
241	export async function coldEmailSendSweep(): Promise<void> {
242	  // ===== GUARDRAIL #1 — MASTER KILL-SWITCH =====
243	  if (!(await getSettingBool("cold_email_sending_enabled", false))) return;
244	
245	  let campaigns: CampaignForSend[];
246	  try {
247	    campaigns = await db.coldCampaign.findMany({
248	      where: { status: "SENDING" },
249	      select: {
250	        id: true,
251	        brandId: true,
252	        listId: true,
253	        launchedAt: true,
254	        sendWindowStart: true,
255	        sendWindowEnd: true,
256	        timezone: true,
257	      },
258	    });
259	  } catch {
260	    // Table not migrated on this environment yet — no-op (mirrors marketing sweep).
261	    return;
262	  }
263	  if (campaigns.length === 0) return;
264	
265	  const protectedSet = protectedDomainSet(await getSetting("cold_email_protected_domains"), appHost());
266	  const ceiling = getSettingIntSafe(await getSetting("coldemail_warmup_ceiling"), 40);
267	  const warmupEnabled = (await getSetting("coldemail_warmup_enabled")) !== "false";
268	  const footerDisclosure = await getSetting("coldemail_footer_disclosure");
269	  const now = new Date();
270	
271	  let transport: MailTransport;
272	  try {
273	    transport = await getTransport("nxeon-smtp");
274	  } catch (err) {
275	    await logEvent("error", "coldemail.transport.init", { message: String(err) });
276	    return;
277	  }
278	
279	  let budget = MAX_SENDS_PER_SWEEP;
280	  for (const campaign of campaigns) {
281	    if (budget <= 0) break;
282	
283	    const brand = await db.brand.findUnique({ where: { id: campaign.brandId } });
284	    if (!brand) continue;
285	
286	    // ===== GUARDRAILS #2 + #3 — reputation isolation + per-brand gate =====
287	    const eligibility = evaluateSendEligibility(brand, protectedSet);
288	    if (!eligibility.eligible) {
289	      await logEvent("warn", "coldemail.send.brand_blocked", {
290	        campaignId: campaign.id,
291	        brandId: brand.id,
292	        reasons: eligibility.reasons,
293	      });
294	      continue;
295	    }
296	
297	    const identity: SendIdentity = {
298	      id: brand.id,
299	      name: brand.name,
300	      fromName: brand.fromName,
301	      fromEmail: brand.fromEmail,
302	      replyTo: brand.replyTo,
303	      sendingDomain: brand.sendingDomain,
304	      physicalPostalAddress: brand.physicalPostalAddress,
305	    };
306	
307	    try {
308	      await scheduleCampaignSends(campaign);
309	      const sent = await processDueSends(campaign, identity, {
310	        now,
311	        transport,
312	        ceiling,
313	        warmupEnabled,
314	        footerDisclosure,
315	        budget,
316	      });
317	      budget -= sent;
318	      await maybeCompleteCampaign(campaign.id);
319	    } catch (err) {
320	      await logEvent("error", "coldemail.send.campaign", { campaignId: campaign.id, message: String(err) });
321	    }
322	  }
323	}
324	
325	function getSettingIntSafe(raw: string, fallback: number): number {
326	  const n = Number(raw);
327	  return Number.isFinite(n) && n > 0 ? Math.floor(n) : fallback;
328	}
