30	// ---------------------------------------------------------------------------
31	// CSV parsing (server-side, no dependency). Handles quoted fields, embedded
32	// commas/newlines, and doubled quotes. First non-empty row is the header.
33	// ---------------------------------------------------------------------------
34	
35	function parseCsv(text: string): { headers: string[]; rows: string[][] } {
36	  const records: string[][] = [];
37	  let field = "";
38	  let row: string[] = [];
39	  let inQuotes = false;
40	  const src = text.replace(/\r\n?/g, "\n");
41	
42	  for (let i = 0; i < src.length; i++) {
43	    const c = src[i];
44	    if (inQuotes) {
45	      if (c === '"') {
46	        if (src[i + 1] === '"') {
47	          field += '"';
48	          i++;
49	        } else {
50	          inQuotes = false;
51	        }
52	      } else {
53	        field += c;
54	      }
55	    } else if (c === '"') {
56	      inQuotes = true;
57	    } else if (c === ",") {
58	      row.push(field);
59	      field = "";
60	    } else if (c === "\n") {
61	      row.push(field);
62	      records.push(row);
63	      row = [];
64	      field = "";
65	    } else {
66	      field += c;
67	    }
68	  }
69	  // Flush trailing field/row.
70	  if (field.length > 0 || row.length > 0) {
71	    row.push(field);
72	    records.push(row);
73	  }
74	
75	  const nonEmpty = records.filter((r) => r.some((v) => v.trim() !== ""));
76	  if (nonEmpty.length === 0) return { headers: [], rows: [] };
77	  const headers = nonEmpty[0].map((h) => h.trim().toLowerCase());
78	  return { headers, rows: nonEmpty.slice(1) };
79	}
