372	  // Verification flags are config-only in Phase 1 (no live DNS check).
373	  const spfVerified = formData.get("spfVerified") === "on" || formData.get("spfVerified") === "true";
374	  const dkimVerified = formData.get("dkimVerified") === "on" || formData.get("dkimVerified") === "true";
