377	  const { id, ...rest } = parsed.data;
378	  const data = { ...rest, spfVerified, dkimVerified, dmarcVerified };
379	  try {
380	    if (id) {
381	      await db.brand.update({ where: { id }, data });
382	    } else {
383	      await db.brand.create({ data });
384	    }
385	  } catch (err) {
386	    await logEvent("error", "coldemail.brand.save", { message: String(err) });
387	    return { error: "Could not save the brand. Please try again." };
