485	/**
486	 * Dry-run a DRAFT campaign: for its list, how many recipients would be
487	 * SUPPRESSED, how many lack a recorded consent basis, and how many are
488	 * sendable — WITHOUT sending, scheduling, or writing anything. Blocked (with the
489	 * missing-requirement list) if the brand fails requireBrandCompliance.
490	 */
491	export async function previewCampaign(campaignId: string): Promise<CampaignPreview | { error: string }> {
492	  await requireArea("platform");
493	
494	  const campaign = await db.coldCampaign.findUnique({
495	    where: { id: campaignId },
496	    include: { brand: true },
497	  });
498	  if (!campaign) return { error: "Campaign not found." };
499	
500	  const missing = requireBrandCompliance(campaign.brand);
501	  if (missing.length > 0) {
502	    return {
503	      blocked: true,
504	      missingRequirements: missing.map((m) => m.label),
505	      total: 0,
506	      suppressed: 0,
507	      missingConsent: 0,
508	      sendable: 0,
509	    };
510	  }
511	
512	  const members = await db.emailListMember.findMany({
513	    where: { listId: campaign.listId },
514	    select: {
515	      contact: {
516	        select: { id: true, email: true, consentRecords: { select: { id: true }, take: 1 } },
517	      },
518	    },
519	  });
520	
521	  const suppressions: SuppressionLike[] = await db.suppression.findMany({
522	    where: { OR: [{ scope: "GLOBAL" }, { scope: "BRAND", brandId: campaign.brandId }] },
523	    select: { email: true, domain: true, scope: true, brandId: true },
524	  });
525	
526	  let suppressed = 0;
527	  let missingConsent = 0;
528	  let sendable = 0;
529	  for (const m of members) {
530	    const email = m.contact.email;
531	    if (isSuppressed(email, campaign.brandId, suppressions)) {
532	      suppressed++;
533	      continue;
534	    }
535	    if (m.contact.consentRecords.length === 0) {
536	      missingConsent++;
537	      continue;
538	    }
539	    sendable++;
540	  }
541	
542	  return {
543	    blocked: false,
544	    missingRequirements: [],
545	    total: members.length,
546	    suppressed,
547	    missingConsent,
548	    sendable,
549	  };
550	}
