620	/** Minutes-from-midnight for an "HH:MM" string, or null if blank/invalid. */
621	function parseHhmm(v: string): number | null {
622	  const m = /^(\d{1,2}):(\d{2})$/.exec(v.trim());
623	  if (!m) return null;
624	  const h = Number(m[1]);
625	  const min = Number(m[2]);
626	  if (h > 23 || min > 59) return null;
627	  return h * 60 + min;
628	}
