630	/** Set a campaign's send window + timezone (both optional). */
631	export async function scheduleCampaign(_prev: ActionState, formData: FormData): Promise<ActionState> {
632	  await requireArea("platform");
633	  const campaignId = String(formData.get("campaignId") ?? "").trim();
634	  if (!campaignId) return { error: "Missing campaign." };
635	  const startRaw = String(formData.get("sendWindowStart") ?? "").trim();
636	  const endRaw = String(formData.get("sendWindowEnd") ?? "").trim();
637	  const timezone = String(formData.get("timezone") ?? "UTC").trim().slice(0, 64) || "UTC";
638	
639	  const sendWindowStart = startRaw ? parseHhmm(startRaw) : null;
640	  const sendWindowEnd = endRaw ? parseHhmm(endRaw) : null;
641	  if ((startRaw && sendWindowStart === null) || (endRaw && sendWindowEnd === null)) {
642	    return { error: "Send window times must be HH:MM (24-hour)." };
643	  }
644	  // Both or neither — a one-sided window is ambiguous.
645	  if ((sendWindowStart === null) !== (sendWindowEnd === null)) {
646	    return { error: "Set both a start and an end time, or leave both blank." };
647	  }
648	
649	  await db.coldCampaign.update({
650	    where: { id: campaignId },
651	    data: { sendWindowStart, sendWindowEnd, timezone },
652	  });
653	  revalidatePath(`/admin/coldemail/campaigns/${campaignId}`);
654	  return { ok: true };
655	}
