690	export async function addSuppression(_prev: ActionState, formData: FormData): Promise<ActionState> {
691	  await requireArea("platform");
692	  const rawValue = String(formData.get("value") ?? "").trim().toLowerCase();
693	  const kind = String(formData.get("kind") ?? "email"); // "email" | "domain"
694	  const reasonRaw = String(formData.get("reason") ?? "MANUAL");
695	  const reason = (SUPPRESSION_REASONS as readonly string[]).includes(reasonRaw)
696	    ? (reasonRaw as (typeof SUPPRESSION_REASONS)[number])
697	    : "MANUAL";
698	  if (!rawValue) return { error: "Enter an email address or domain." };
699	
700	  const isEmail = kind === "email";
701	  if (isEmail && !emailSchema.safeParse(rawValue).success) return { error: "Enter a valid email address." };
702	  if (!isEmail && !/^[a-z0-9.-]+\.[a-z]{2,}$/.test(rawValue)) return { error: "Enter a valid domain." };
703	
704	  const where = isEmail
705	    ? { scope: "GLOBAL" as const, email: rawValue }
706	    : { scope: "GLOBAL" as const, domain: rawValue };
707	  const existing = await db.suppression.findFirst({ where, select: { id: true } });
708	  if (!existing) {
709	    await db.suppression.create({
710	      data: isEmail
711	        ? { scope: "GLOBAL", email: rawValue, reason }
712	        : { scope: "GLOBAL", domain: rawValue, reason },
713	    });
714	  }
715	  revalidatePath("/admin/coldemail/suppression");
716	  revalidatePath("/admin/coldemail");
717	  return { ok: true };
