728	/** Bulk import suppression entries (one email or domain per line, or CSV). */
729	export async function importSuppressionCsv(_prev: ActionState, formData: FormData): Promise<ActionState> {
730	  await requireArea("platform");
731	  const text = String(formData.get("csv") ?? "");
732	  if (!text.trim()) return { error: "Paste some addresses or domains first." };
733	
734	  const tokens = text
735	    .split(/[\n,;\s]+/)
736	    .map((t) => t.trim().toLowerCase())
737	    .filter(Boolean);
738	
739	  let added = 0;
740	  let skipped = 0;
741	  for (const t of tokens) {
742	    const isEmail = t.includes("@");
743	    const valid = isEmail ? emailSchema.safeParse(t).success : /^[a-z0-9.-]+\.[a-z]{2,}$/.test(t);
744	    if (!valid) {
745	      skipped++;
746	      continue;
747	    }
748	    const where = isEmail ? { scope: "GLOBAL" as const, email: t } : { scope: "GLOBAL" as const, domain: t };
749	    const existing = await db.suppression.findFirst({ where, select: { id: true } });
750	    if (existing) {
751	      skipped++;
752	      continue;
753	    }
754	    await db.suppression.create({
755	      data: isEmail
756	        ? { scope: "GLOBAL", email: t, reason: "MANUAL" }
757	        : { scope: "GLOBAL", domain: t, reason: "MANUAL" },
758	    });
759	    added++;
760	  }
761	  revalidatePath("/admin/coldemail/suppression");
762	  revalidatePath("/admin/coldemail");
763	  return { ok: true, error: `Added ${added} entries. ${skipped} skipped (invalid or duplicate).` };
764	}
