780	  const protectedDomains = String(formData.get("cold_email_protected_domains") ?? "").trim().slice(0, 600);
781	  const warmupEnabled = formData.get("coldemail_warmup_enabled") === "on" || formData.get("coldemail_warmup_enabled") === "true";
