784	  const thresholdRaw = Number(formData.get("coldemail_complaint_threshold"));
785	  const threshold = Number.isFinite(thresholdRaw) && thresholdRaw > 0 ? Math.min(thresholdRaw, 1) : 0.003;
786	
787	  await setSetting("coldemail_daily_cap", String(cap));
788	  await setSetting("coldemail_default_consent_basis", basis);
