// Cold Email Engine — warmup engine (Phase 3).
//
// PURE + unit-testable: NO database access, NO I/O, NO network. The warmup
// worker step and the Warming UI both call these functions, and the test suite
// (test/coldemail-phase3.test.ts) exercises the ramp math directly.
//
// What "warming" means here (per the 2026 research): a brand-new inbox starts at
// a handful of sends/day and ramps to a safe ceiling over 2–4 weeks so the
// mailbox provider builds a history of trusted, low-and-slow sending before any
// real campaign volume. This module computes the ALLOWED volume for an inbox on
// a given day — it never sends anything.
//
// Honesty note baked into the design (research §2): we favour REAL-engagement
// warmup (genuine replies + spam-rescue on a vetted seed) over a synthetic
// auto-open pool, because Gmail/Yahoo increasingly detect and penalise synthetic
// warmup patterns. A synthetic warmup NETWORK that sends real mail between pooled
// mailboxes is deliberately OUT OF SCOPE (SaaS-pool territory) — see WARMUP_MODES.

import { warmupDayIndex } from "@/lib/coldemail/compliance";

export type WarmupStrategyKey = "CONSERVATIVE" | "STANDARD" | "AGGRESSIVE" | "ADAPTIVE";
export type WarmupModeKey = "POOL" | "REAL_SEED" | "HYBRID";

/** A warmup ramp definition: from `startCap`/day up to `targetCap`/day over `rampDays`. */
export type WarmupPlan = {
  startCap: number;
  targetCap: number;
  rampDays: number;
};

/**
 * Consensus 2026 ramp presets (research §2). New inbox ≈5–10/day → 30–50/day over
 * 2–4 weeks. AGGRESSIVE mirrors "pre-warmed inbox" guidance (start higher, ramp
 * faster) and should only be used on inboxes with prior sending history.
 */
export const WARMUP_PRESETS: Record<WarmupStrategyKey, WarmupPlan> = {
  CONSERVATIVE: { startCap: 5, targetCap: 30, rampDays: 28 },
  STANDARD: { startCap: 5, targetCap: 40, rampDays: 21 },
  AGGRESSIVE: { startCap: 10, targetCap: 50, rampDays: 14 },
  ADAPTIVE: { startCap: 5, targetCap: 40, rampDays: 21 },
};

/**
 * Warmup modes and their honesty posture. The default is HYBRID/REAL_SEED; POOL
 * (synthetic auto-opens between simulated inboxes) carries an explicit warning
 * because it can be detected and hurt deliverability in 2026.
 */
export const WARMUP_MODES: Record<WarmupModeKey, { label: string; safe: boolean; note: string }> = {
  REAL_SEED: {
    label: "Real seed",
    safe: true,
    note: "Genuine replies + spam-rescue from a small vetted seed audience. Safest posture in 2026.",
  },
  HYBRID: {
    label: "Hybrid",
    safe: true,
    note: "Mostly real-engagement with limited pooled signals. Recommended default.",
  },
  POOL: {
    label: "Synthetic pool",
    safe: false,
    note: "Artificial opens/replies between simulated inboxes. Gmail/Yahoo increasingly detect this and it can DAMAGE deliverability. A real shared warmup network cannot be self-hosted (SaaS-pool territory) — out of scope.",
  },
};

/** Clamp a plan into sane bounds so bad input can never produce an uncapped ramp. */
export function normalizePlan(plan: Partial<WarmupPlan> | null | undefined): WarmupPlan {
  const startCap = clampInt(plan?.startCap, 1, 200, 5);
  const targetCap = clampInt(plan?.targetCap, startCap, 500, Math.max(startCap, 40));
  const rampDays = clampInt(plan?.rampDays, 1, 90, 21);
  return { startCap, targetCap, rampDays };
}

function clampInt(v: unknown, min: number, max: number, fallback: number): number {
  const n = Math.floor(Number(v));
  if (!Number.isFinite(n)) return fallback;
  return Math.min(max, Math.max(min, n));
}

/**
 * The allowed daily volume for an inbox on warmup `dayIndex` (0-based: day 0 = the
 * first day → startCap). Linear ramp from startCap to targetCap across rampDays;
 * clamps to targetCap once the ramp completes. Deterministic and pure.
 */
export function warmupDailyLimit(dayIndex: number, plan: WarmupPlan): number {
  const p = normalizePlan(plan);
  const day = Number.isFinite(dayIndex) ? Math.max(0, Math.floor(dayIndex)) : 0;
  if (day <= 0) return p.startCap;
  if (day >= p.rampDays) return p.targetCap;
  const ramped = p.startCap + (p.targetCap - p.startCap) * (day / p.rampDays);
  return Math.min(p.targetCap, Math.max(p.startCap, Math.round(ramped)));
}

/** Has the inbox finished its ramp (reached targetCap)? */
export function isWarmupComplete(dayIndex: number, plan: WarmupPlan): boolean {
  const p = normalizePlan(plan);
  return (Number.isFinite(dayIndex) ? Math.floor(dayIndex) : 0) >= p.rampDays;
}

/**
 * ADAPTIVE back-off: when an inbox's health score dips, shrink today's allowance
 * rather than pushing full ramp volume through a struggling inbox (research §2/§4
 * "adaptive ramp down on soft-bounce spikes"). Healthy (≥80) → no change;
 * 60–79 → half; <60 → quarter. Never drops below 1.
 */
export function applyHealthBackoff(limit: number, healthScore: number): number {
  const h = Number.isFinite(healthScore) ? healthScore : 100;
  const base = Math.max(0, Math.floor(limit));
  if (h >= 80) return base;
  if (h >= 60) return Math.max(1, Math.round(base * 0.5));
  return Math.max(1, Math.round(base * 0.25));
}

export type AllowedVolumeOpts = {
  warmupStartedAt?: Date | string | null;
  plan: WarmupPlan;
  /** Absolute per-inbox ceiling — the warmup ramp is additionally clamped by this. */
  dailyCap?: number;
  /** For ADAPTIVE: the inbox health score (0–100). */
  healthScore?: number;
  adaptive?: boolean;
  now?: Date | number;
};

/**
 * Today's allowed send volume for an inbox: the warmup ramp value for the current
 * warmup day, clamped by the inbox's absolute dailyCap, with an optional adaptive
 * health back-off. `warmupStartedAt = null` means the inbox is on day 0 (never
 * uncapped). This is the single number the rotation engine budgets against.
 */
export function inboxAllowedVolume(opts: AllowedVolumeOpts): number {
  const plan = normalizePlan(opts.plan);
  const day = warmupDayIndex(opts.warmupStartedAt ?? null, opts.now ?? Date.now());
  let limit = warmupDailyLimit(day, plan);
  if (opts.adaptive) limit = applyHealthBackoff(limit, opts.healthScore ?? 100);
  const cap = opts.dailyCap && opts.dailyCap > 0 ? Math.floor(opts.dailyCap) : plan.targetCap;
  return Math.max(0, Math.min(limit, cap));
}

/** The planned-ramp curve (day → planned volume) for charting the warmup. */
export function warmupRampCurve(plan: WarmupPlan): { day: number; planned: number }[] {
  const p = normalizePlan(plan);
  const out: { day: number; planned: number }[] = [];
  for (let d = 0; d <= p.rampDays; d++) out.push({ day: d, planned: warmupDailyLimit(d, p) });
  return out;
}

export type WarmupStatus = {
  complete: boolean;
  day: number;
  rampDays: number;
  currentLimit: number;
  targetCap: number;
  label: string;
};

/**
 * A plain-language warmup status for the UI: "Warming — day 9 of 21, ramping to
 * 40/day" or "Warmed — sending up to 40/day". `dayIndex` is 0-based; the label
 * shows 1-based days so a human reads "day 1" on the first day.
 */
export function warmupStatus(dayIndex: number, plan: WarmupPlan): WarmupStatus {
  const p = normalizePlan(plan);
  const day = Number.isFinite(dayIndex) ? Math.max(0, Math.floor(dayIndex)) : 0;
  const complete = day >= p.rampDays;
  const currentLimit = warmupDailyLimit(day, p);
  const label = complete
    ? `Warmed — sending up to ${p.targetCap}/day`
    : `Warming — day ${day + 1} of ${p.rampDays}, ramping to ${p.targetCap}/day (today ${currentLimit})`;
  return { complete, day, rampDays: p.rampDays, currentLimit, targetCap: p.targetCap, label };
}

// Cold Email Engine — send rotation + health-based auto-pause (Phase 3).
//
// PURE + unit-testable: NO database access, NO I/O. The send worker feeds it the
// inbox rows + today's counts and it decides (a) WHICH inbox sends the next
// message and (b) WHEN an inbox or a whole domain must auto-pause because its
// bounce/complaint rate crossed a burn threshold. Keeping this pure means the
// exact rotation + threshold logic the worker runs is what the tests assert.
//
// Thresholds come from research §4 and default here, but the worker sources the
// live values from Settings so an operator can tune them.

// ---------------------------------------------------------------------------
// Rotation
// ---------------------------------------------------------------------------

export type InboxStatusLike = "WARMING" | "ACTIVE" | "PAUSED" | "BURNING";

/** The minimal inbox shape the rotation engine needs. */
export type RotationInbox = {
  id: string;
  status: InboxStatusLike;
  /** Today's allowed volume from the warmup engine (already cap-clamped). */
  allowedToday: number;
  /** Real sends already made by this inbox today. */
  sentToday: number;
  /** Domain SPF+DKIM+DMARC all verified? An inbox on an unauthenticated domain never sends. */
  authGreen: boolean;
  /** Last real send — used to spread load (least-recently-used) + honour the min gap. */
  lastSendAt?: Date | string | null;
  /** Minimum seconds between sends from this inbox (90–120 typical). */
  minGapSeconds?: number;
};

/** Remaining sends an inbox may still make today (never negative). */
export function remainingCapacity(i: RotationInbox): number {
  return Math.max(0, Math.floor(i.allowedToday) - Math.floor(i.sentToday));
}

function toMs(d: Date | string | null | undefined): number | null {
  if (!d) return null;
  const t = d instanceof Date ? d.getTime() : new Date(d).getTime();
  return Number.isFinite(t) ? t : null;
}

/**
 * Is this inbox eligible to send RIGHT NOW? Requires: status ACTIVE (WARMING
 * inboxes build reputation but must not carry campaign traffic; PAUSED/BURNING
 * never send), the domain authenticated, remaining daily capacity, and at least
 * `minGapSeconds` elapsed since its last send.
 */
export function isInboxEligible(i: RotationInbox, now: Date | number = Date.now()): { eligible: boolean; reason?: string } {
  if (i.status !== "ACTIVE") return { eligible: false, reason: `status ${i.status}` };
  if (!i.authGreen) return { eligible: false, reason: "domain not authenticated (SPF/DKIM/DMARC)" };
  if (remainingCapacity(i) <= 0) return { eligible: false, reason: "daily cap reached" };
  const gap = Math.max(0, i.minGapSeconds ?? 0) * 1000;
  if (gap > 0) {
    const last = toMs(i.lastSendAt);
    const nowMs = now instanceof Date ? now.getTime() : now;
    if (last !== null && nowMs - last < gap) return { eligible: false, reason: "within min send gap" };
  }
  return { eligible: true };
}

/**
 * Pick the next inbox to send from among a brand's inboxes: the eligible inbox
 * that sent least recently (spreads load, avoids clustering), tie-broken by most
 * remaining capacity. Returns null when none are eligible. Note `lastSendAt` here
 * is the PERSISTED value — the worker updates it after each send so successive
 * calls rotate. The min-gap check uses the same field.
 */
export function selectNextInbox(inboxes: RotationInbox[], now: Date | number = Date.now()): RotationInbox | null {
  const eligible = inboxes.filter((i) => isInboxEligible(i, now).eligible);
  if (eligible.length === 0) return null;
  eligible.sort((a, b) => {
    const la = toMs(a.lastSendAt) ?? 0;
    const lb = toMs(b.lastSendAt) ?? 0;
    if (la !== lb) return la - lb; // oldest first
    return remainingCapacity(b) - remainingCapacity(a); // then most headroom
  });
  return eligible[0];
}

/**
 * Plan how to distribute `count` sends across a brand's inboxes for a sweep,
 * ignoring the time-gap (the worker throttles between sends) but honouring each
 * inbox's remaining capacity. Round-robin by remaining capacity so no single
 * inbox is drained first. Returns an ordered list of inbox ids (length ≤ count).
 * Pure — used by the worker and asserted by tests.
 */
export function planRotation(inboxes: RotationInbox[], count: number): string[] {
  const budget: Record<string, number> = {};
  const pool = inboxes.filter((i) => i.status === "ACTIVE" && i.authGreen);
  for (const i of pool) budget[i.id] = remainingCapacity(i);
  const order: string[] = [];
  let remaining = Math.max(0, Math.floor(count));
  while (remaining > 0) {
    // Pick the inbox with the most remaining budget this round.
    let best: string | null = null;
    for (const id of Object.keys(budget)) {
      if (budget[id] <= 0) continue;
      if (best === null || budget[id] > budget[best]) best = id;
    }
    if (best === null) break; // no capacity anywhere
    order.push(best);
    budget[best] -= 1;
    remaining -= 1;
  }
  return order;
}

// ---------------------------------------------------------------------------
// Auto-pause thresholds (research §4)
// ---------------------------------------------------------------------------

export type BurnThresholds = {
  /** Pause a single INBOX at/above this bounce rate (per inbox/day). */
  bouncePauseInbox: number;
  /** Pause the whole DOMAIN when bounce stays at/above this. */
  bouncePauseDomain: number;
  /** Hard stop + require re-verification at/above this bounce rate. */
  bounceHardStop: number;
  /** Warn (amber) at/above this bounce rate. */
  bounceWarn: number;
  /** Pause the whole DOMAIN at/above this complaint rate + flag targeting. */
  complaintPauseDomain: number;
  /** Warn (amber) at/above this complaint rate. */
  complaintWarn: number;
};

/** Defaults straight from research §4 (auto-pause slightly under the hard ceilings). */
export const DEFAULT_THRESHOLDS: BurnThresholds = {
  bouncePauseInbox: 0.018, // 1.8%
  bouncePauseDomain: 0.02, // 2% sustained
  bounceHardStop: 0.05, // 5%
  bounceWarn: 0.02, // 2%
  complaintPauseDomain: 0.0008, // 0.08%
  complaintWarn: 0.0005, // 0.05%
};

/** Merge partial operator overrides onto the defaults, ignoring bad numbers. */
export function resolveThresholds(overrides?: Partial<BurnThresholds> | null): BurnThresholds {
  const out = { ...DEFAULT_THRESHOLDS };
  if (overrides) {
    for (const k of Object.keys(DEFAULT_THRESHOLDS) as (keyof BurnThresholds)[]) {
      const v = overrides[k];
      if (typeof v === "number" && Number.isFinite(v) && v > 0 && v <= 1) out[k] = v;
    }
  }
  return out;
}

/** Sent/delivered/bounce/complaint counts over the evaluation window. */
export type RateStats = { sent: number; delivered: number; bounces: number; complaints: number };

/** bounces ÷ sent (0 when nothing sent). Combines hard+soft — the caller decides which. */
export function bounceRate(s: RateStats): number {
  return s.sent > 0 ? s.bounces / s.sent : 0;
}

/** complaints ÷ delivered, falling back to sent when delivered is unknown/zero. */
export function complaintRate(s: RateStats): number {
  const denom = s.delivered > 0 ? s.delivered : s.sent;
  return denom > 0 ? s.complaints / denom : 0;
}

export type HealthLevel = "healthy" | "warning" | "danger";

export type AutoPauseVerdict = {
  pause: boolean;
  hardStop: boolean;
  level: HealthLevel;
  reasons: string[];
  rules: string[];
};

const pct = (n: number) => `${(n * 100).toFixed(2)}%`;

/**
 * Evaluate a single INBOX for auto-pause on bounce rate. `minSends` guards against
 * tripping on a handful of sends where a rate is meaningless. A bounce rate at/over
 * `bounceHardStop` sets hardStop (pause + require re-verification).
 */
export function evaluateInboxAutoPause(
  stats: RateStats,
  thresholds: BurnThresholds = DEFAULT_THRESHOLDS,
  minSends = 20,
): AutoPauseVerdict {
  const rules: string[] = [];
  const reasons: string[] = [];
  if (stats.sent < minSends) return { pause: false, hardStop: false, level: "healthy", reasons, rules };

  const br = bounceRate(stats);
  let level: HealthLevel = "healthy";
  let pause = false;
  let hardStop = false;

  if (br >= thresholds.bounceHardStop) {
    pause = true;
    hardStop = true;
    level = "danger";
    rules.push("bounce_hard_stop");
    reasons.push(`Bounce rate ${pct(br)} ≥ hard-stop ${pct(thresholds.bounceHardStop)} — paused, re-verify the list`);
  } else if (br >= thresholds.bouncePauseInbox) {
    pause = true;
    level = "danger";
    rules.push("bounce_pause_inbox");
    reasons.push(`Bounce rate ${pct(br)} ≥ inbox pause ${pct(thresholds.bouncePauseInbox)} — inbox paused`);
  } else if (br >= thresholds.bounceWarn) {
    level = "warning";
    rules.push("bounce_warn");
    reasons.push(`Bounce rate ${pct(br)} approaching the ceiling`);
  }
  return { pause, hardStop, level, reasons, rules };
}

/**
 * Evaluate a whole DOMAIN for auto-pause on bounce AND complaint rate. A domain
 * pauses when its aggregate bounce is sustained over the domain threshold or its
 * complaint rate crosses the pause line (wrong ICP / deceptive copy) — because a
 * single burned domain poisons every recipient on it.
 */
export function evaluateDomainAutoPause(
  stats: RateStats,
  thresholds: BurnThresholds = DEFAULT_THRESHOLDS,
  minSends = 50,
): AutoPauseVerdict {
  const rules: string[] = [];
  const reasons: string[] = [];
  if (stats.sent < minSends) return { pause: false, hardStop: false, level: "healthy", reasons, rules };

  const br = bounceRate(stats);
  const cr = complaintRate(stats);
  let level: HealthLevel = "healthy";
  let pause = false;
  let hardStop = false;

  if (br >= thresholds.bounceHardStop) {
    pause = true;
    hardStop = true;
    level = "danger";
    rules.push("bounce_hard_stop");
    reasons.push(`Domain bounce ${pct(br)} ≥ hard-stop ${pct(thresholds.bounceHardStop)} — domain stopped, re-verify`);
  } else if (br >= thresholds.bouncePauseDomain) {
    pause = true;
    level = "danger";
    rules.push("bounce_pause_domain");
    reasons.push(`Domain bounce ${pct(br)} ≥ domain pause ${pct(thresholds.bouncePauseDomain)} — domain paused`);
  }

  if (cr >= thresholds.complaintPauseDomain) {
    pause = true;
    level = "danger";
    rules.push("complaint_pause_domain");
    reasons.push(`Complaint rate ${pct(cr)} ≥ ${pct(thresholds.complaintPauseDomain)} — domain paused, review targeting`);
  } else if (cr >= thresholds.complaintWarn && level === "healthy") {
    level = "warning";
    rules.push("complaint_warn");
    reasons.push(`Complaint rate ${pct(cr)} approaching the ceiling`);
  }

  if (level === "healthy" && br >= thresholds.bounceWarn) {
    level = "warning";
    rules.push("bounce_warn");
  }
  return { pause, hardStop, level, reasons, rules };
}

// Cold Email Engine — deliverability analytics (Phase 3).
//
// PURE + unit-testable: NO database access, NO I/O. Turns raw event counts into
// the derived rates the dashboards show, and — critically — encodes the 2026
// HONESTY posture about open tracking:
//
//   Apple Mail Privacy Protection pre-loads tracking pixels on Apple's servers,
//   so 50%+ of "opens" are machine-generated. Open rate is therefore surfaced but
//   flagged UNRELIABLE and MUST NOT be a health signal or optimization target.
//   The primary signals are reply / positive-reply, bounce, complaint, click,
//   unsubscribe, and inbox-placement (from seed tests).
//
// The worker rolls DeliverabilityEvent rows into MetricsDaily; this module derives
// the rates from those counts and colours them against the research benchmarks.

// ---------------------------------------------------------------------------
// Counts + derived rates
// ---------------------------------------------------------------------------

/** Raw daily counts for one scope (campaign / inbox / domain / brand). */
export type MetricCounts = {
  sent: number;
  delivered: number;
  hardBounce: number;
  softBounce: number;
  /** UNRELIABLE — MPP/scanner-inflated. Never a health signal. */
  opens: number;
  uniqueClicks: number;
  replies: number;
  positiveReplies: number;
  complaints: number;
  unsubscribes: number;
};

export const ZERO_COUNTS: MetricCounts = {
  sent: 0,
  delivered: 0,
  hardBounce: 0,
  softBounce: 0,
  opens: 0,
  uniqueClicks: 0,
  replies: 0,
  positiveReplies: 0,
  complaints: 0,
  unsubscribes: 0,
};

export type DerivedRates = {
  deliveryRate: number;
  bounceRate: number; // (hard+soft)/sent
  hardBounceRate: number;
  complaintRate: number; // complaints/delivered
  unsubRate: number;
  clickRate: number;
  replyRate: number;
  positiveReplyRate: number;
  /** UNRELIABLE — surfaced for context only, flagged everywhere it appears. */
  openRate: number;
};

const safeDiv = (a: number, b: number) => (b > 0 ? a / b : 0);

/** Add two count buckets — used when rolling many event rows into one daily row. */
export function addCounts(a: MetricCounts, b: Partial<MetricCounts>): MetricCounts {
  const out = { ...a };
  for (const k of Object.keys(ZERO_COUNTS) as (keyof MetricCounts)[]) {
    out[k] = (a[k] ?? 0) + (b[k] ?? 0);
  }
  return out;
}

/**
 * Derive every rate from a count bucket. Delivered is the denominator for the
 * engagement/complaint rates (they only make sense over accepted mail); bounce is
 * over sent. Divide-by-zero is 0, never NaN.
 */
export function deriveRates(m: MetricCounts): DerivedRates {
  const bounces = (m.hardBounce ?? 0) + (m.softBounce ?? 0);
  return {
    deliveryRate: safeDiv(m.delivered, m.sent),
    bounceRate: safeDiv(bounces, m.sent),
    hardBounceRate: safeDiv(m.hardBounce, m.sent),
    complaintRate: safeDiv(m.complaints, m.delivered),
    unsubRate: safeDiv(m.unsubscribes, m.delivered),
    clickRate: safeDiv(m.uniqueClicks, m.delivered),
    replyRate: safeDiv(m.replies, m.delivered),
    positiveReplyRate: safeDiv(m.positiveReplies, m.delivered),
    openRate: safeDiv(m.opens, m.delivered),
  };
}

// ---------------------------------------------------------------------------
// Open-rate honesty (surfaced by every UI that shows an open number)
// ---------------------------------------------------------------------------

export const OPEN_RATE_UNRELIABLE = true;
export const OPEN_RATE_LABEL = "Open rate (unreliable)";
export const OPEN_RATE_WARNING =
  "Unreliable (MPP-inflated) — do not optimize on this. Apple Mail Privacy Protection auto-opens 50%+ of email and corporate scanners pre-fetch pixels, so opens are machine-generated noise.";

/** The signals leaders actually optimise on in 2026 (research §4). */
export const PRIMARY_SIGNALS = [
  "positiveReplyRate",
  "replyRate",
  "bounceRate",
  "complaintRate",
  "clickRate",
  "unsubRate",
  "inboxPlacementRate",
] as const;

// ---------------------------------------------------------------------------
// Benchmark bands (research §4) → red/amber/green
// ---------------------------------------------------------------------------

export type Band = "green" | "amber" | "red";

/** Bounce: <2% green · 2–5% amber · >5% red (research §4). */
export function bounceBand(rate: number): Band {
  if (rate < 0.02) return "green";
  if (rate < 0.05) return "amber";
  return "red";
}

/** Complaint: <0.05% green · 0.05–0.08% amber · >0.08% red (research §4). */
export function complaintBand(rate: number): Band {
  if (rate < 0.0005) return "green";
  if (rate < 0.0008) return "amber";
  return "red";
}

/** Inbox placement: ≥90% green · 80–90% amber · <80% red (research §4). */
export function placementBand(rate: number): Band {
  if (rate >= 0.9) return "green";
  if (rate >= 0.8) return "amber";
  return "red";
}

// ---------------------------------------------------------------------------
// Inbox-placement (seed test) result
// ---------------------------------------------------------------------------

export type PlacementResult = {
  inboxPct: number;
  spamPct: number;
  promotionsPct: number;
  missingPct: number;
};

/** Normalise seed-test percentages to fractions summing ≤1 (defensive). */
export function normalizePlacement(p: Partial<PlacementResult>): PlacementResult {
  const f = (v: unknown) => {
    let n = Number(v);
    if (!Number.isFinite(n) || n < 0) n = 0;
    if (n > 1) n = n / 100; // accept whole-percent inputs
    return Math.min(1, n);
  };
  return {
    inboxPct: f(p.inboxPct),
    spamPct: f(p.spamPct),
    promotionsPct: f(p.promotionsPct),
    missingPct: f(p.missingPct),
  };
}

// ---------------------------------------------------------------------------
// Composite health score (0–100) — deliberately excludes open rate
// ---------------------------------------------------------------------------

/**
 * A 0–100 health score from the MPP-proof signals only: bounce, complaint and
 * unsubscribe penalise; a healthy reply rate lifts. Opens are NEVER an input —
 * that is the whole point. Placement (when known) pulls the score toward the
 * seed-test truth. Returns 100 when there is no volume to judge.
 */
export function healthScore(m: MetricCounts, placement?: PlacementResult | null): number {
  if (m.sent <= 0) return 100;
  const r = deriveRates(m);
  let score = 100;
  // Bounce: every 1% over 0 costs ~12 points (5% ≈ -60).
  score -= Math.min(60, (r.bounceRate / 0.01) * 12);
  // Complaint: brutal — 0.1% ≈ -30, 0.3% ≈ -90.
  score -= Math.min(90, (r.complaintRate / 0.001) * 30);
  // Unsubscribe: mild disengagement signal.
  score -= Math.min(15, (r.unsubRate / 0.01) * 5);
  // Reply rate rewards genuine engagement (cap +10).
  score += Math.min(10, (r.replyRate / 0.02) * 5);
  if (placement) {
    // Blend 30% toward measured inbox placement when we have a seed test.
    score = score * 0.7 + placement.inboxPct * 100 * 0.3;
  }
  return Math.max(0, Math.min(100, Math.round(score)));
}

export type HealthLevel = "healthy" | "warning" | "danger";

/** Map a composite health score to a status band for badges/colours. */
export function healthLevel(score: number): HealthLevel {
  if (score >= 75) return "healthy";
  if (score >= 50) return "warning";
  return "danger";
}

/** Format a fraction as a percent string for display (e.g. 0.0123 → "1.23%"). */
export function formatPct(rate: number, dp = 2): string {
  if (!Number.isFinite(rate)) return "—";
  return `${(rate * 100).toFixed(dp)}%`;
}

input.new_string:
enum EmailEventType {
  OPEN
  CLICK
  BOUNCE
  COMPLAINT
  UNSUBSCRIBE
  SENT
  DELIVERED
  FAILED
  // Phase 3 additions (append-only — never reorder/remove). REPLY/POSITIVE_REPLY
  // are the MPP-proof KPIs; HARD_BOUNCE/SOFT_BOUNCE split the old BOUNCE; DEFERRED
  // is a temporary 4xx. Legacy BOUNCE rows remain valid.
  REPLY
  POSITIVE_REPLY
  HARD_BOUNCE
  SOFT_BOUNCE
  DEFERRED
}

// ============================================================================
// Cold Email Engine (Phase 3) — deliverability + scale layer.
//
// Multi-domain / multi-inbox rotation, per-inbox warmup, honest deliverability
// analytics, and health-based auto-pause. ADDITIVE to Phase 1/2: no existing
// model/enum value is changed. Nothing here sends — the master kill-switch
// `cold_email_sending_enabled` still gates the worker.
// ============================================================================

/// Lifecycle of a dedicated sending domain.
enum SendingDomainStatus {
  PENDING // registered, auth not yet verified
  WARMING // authenticated, inboxes ramping
  ACTIVE // cleared to carry campaign volume
  PAUSED // auto-paused (bounce/complaint) or by an operator
  BURNED // reputation destroyed — retire it
}

/// Per-inbox lifecycle. WARMING inboxes build reputation but never carry campaign
/// traffic; only ACTIVE inboxes are eligible for rotation.
enum InboxStatus {
  WARMING
  ACTIVE
  PAUSED
  BURNING
}

/// Where a mailbox physically lives — informs provider-specific caps/shaping.
enum MailboxProvider {
  GMAIL
  M365
  SMTP
  POSTAL
  KUMO
}

/// Published DMARC policy for a sending domain (min p=none to reach the inbox in 2026).
enum DmarcPolicy {
  NONE
  QUARANTINE
  REJECT
}

/// Warmup ramp aggressiveness (see lib/coldemail/warmup.ts WARMUP_PRESETS).
enum WarmupStrategy {
  CONSERVATIVE
  STANDARD
  AGGRESSIVE
  ADAPTIVE
}

/// Warmup engagement mode. HYBRID/REAL_SEED are safe; POOL (synthetic pool) is
/// flagged risky — a real shared warmup network is out of scope (SaaS-pool territory).
enum WarmupMode {
  POOL
  REAL_SEED
  HYBRID
}

/// Append-only deliverability event types (the analytics spine). Broader than
/// EmailEventType so seed tests + provider DSNs fit without touching Phase 1/2.
enum DeliverabilityEventType {
  SENT
  DELIVERED
  DEFERRED
  HARD_BOUNCE
  SOFT_BOUNCE
  OPEN
  CLICK
  REPLY
  POSITIVE_REPLY
  COMPLAINT
  UNSUBSCRIBE
  PLACEMENT_TEST
}

/// Grain of a metrics/health rollup row.
enum MetricsScope {
  CAMPAIGN
  INBOX
  DOMAIN
  BRAND
}

/// Health snapshot status band.
enum HealthStatus {
  HEALTHY
  WARNING
  DANGER
  PAUSED
}

/// Source of an inbox-placement (seed) test.
enum PlacementProvider {
  GLOCKAPPS
  MAILREACH
  MANUAL_SEED
}

/// A dedicated cold-email sending domain owned by a Brand. Reputation is isolated
/// on these lookalike/subdomain domains so a burn never touches the primary brand
/// domain or the platform's transactional reputation (see reputation isolation).
model SendingDomain {
  id                     String              @id @default(cuid())
  brandId                String
  domain                 String // apex, e.g. try-brand.com
  subdomain              String              @default("mail") // outreach subdomain strategy (mail. / outreach.)
  isPrimary              Boolean             @default(false)
  status                 SendingDomainStatus @default(PENDING)
  // Authentication (RFC + Yahoogle/Outlook 2026). Config-only flags until a live
  // DNS verifier lands; the readiness panel reflects them.
  spfVerified            Boolean             @default(false)
  dkimVerified           Boolean             @default(false)
  dmarcVerified          Boolean             @default(false)
  dmarcPolicy            DmarcPolicy         @default(NONE)
  // Custom tracking domain (t.mail-brand.com) — shared tracking domains are
  // blocklisted and tank placement, so a custom one is a readiness requirement.
  trackingDomain         String              @default("")
  trackingDomainVerified Boolean             @default(false)
  // RFC 8058 one-click unsubscribe supported on this domain's mail.
  oneClickUnsub          Boolean             @default(true)
  reputationScore        Int                 @default(100)
  addedAt                DateTime            @default(now())
  warmupStartedAt        DateTime?
  lastCheckedAt          DateTime?
  pausedReason           String              @default("")

  brand          Brand                 @relation(fields: [brandId], references: [id], onDelete: Cascade)
  inboxes        Inbox[]
  events         DeliverabilityEvent[]
  placementTests PlacementTest[]

  @@unique([brandId, domain, subdomain])
  @@index([brandId])
  @@index([status])
}

/// A single mailbox on a SendingDomain. Rotation distributes a campaign's sends
/// across a brand's ACTIVE inboxes, each capped by its warmup ramp + dailyCap.
model Inbox {
  id              String          @id @default(cuid())
  sendingDomainId String
  email           String          @unique
  provider        MailboxProvider @default(SMTP)
  status          InboxStatus     @default(WARMING)
  // Absolute per-inbox/day ceiling (warmup-safe, 20–40 typical for a warmed inbox).
  dailyCap        Int             @default(40)
  // Today's warmup-ramped allowance (recomputed by the warmup sweep). Never exceeds dailyCap.
  currentRampCap  Int             @default(5)
  warmupDay       Int             @default(0)
  warmupStartedAt DateTime?
  // Warmup plan (folded onto the inbox — one plan per inbox).
  strategy        WarmupStrategy  @default(STANDARD)
  warmupMode      WarmupMode      @default(HYBRID)
  startCap        Int             @default(5)
  targetCap       Int             @default(40)
  rampDays        Int             @default(21)
  // Send pacing.
  sendWindowStart Int? // minutes-from-midnight
  sendWindowEnd   Int?
  minGapSeconds   Int             @default(100) // 90–120s between sends reads human
  healthScore     Int             @default(100)
  reputationScore Int             @default(100)
  lastSendAt      DateTime?
  pausedReason    String          @default("")
  createdAt       DateTime        @default(now())

  sendingDomain SendingDomain         @relation(fields: [sendingDomainId], references: [id], onDelete: Cascade)
  warmupStates  WarmupState[]
  events        DeliverabilityEvent[]
  sends         ColdSend[]

  @@index([sendingDomainId])
  @@index([status])
  @@index([lastSendAt])
}

/// Per-inbox, per-day warmup state — the planned vs actual ramp curve the Warming
/// UI charts, plus the engagement signals that ran (replies, spam-rescues).
model WarmupState {
  id            String   @id @default(cuid())
  inboxId       String
  date          DateTime // UTC day
  day           Int // warmup day index (0-based)
  plannedVolume Int      @default(0)
  sentVolume    Int      @default(0)
  warmupReplies Int      @default(0)
  spamRescues   Int      @default(0)
  healthScore   Int      @default(100)
  createdAt     DateTime @default(now())

  inbox Inbox @relation(fields: [inboxId], references: [id], onDelete: Cascade)

  @@unique([inboxId, date])
  @@index([inboxId])
  @@index([date])
}

/// Append-only deliverability event — the analytics spine. Everything (rollups,
/// health, auto-pause) derives from these rows. `campaignId`/`contactId`/`sendId`
/// are loose scalar ids (no FK) to keep this additive and contained.
model DeliverabilityEvent {
  id              String                  @id @default(cuid())
  inboxId         String?
  sendingDomainId String?
  campaignId      String?
  contactId       String?
  sendId          String?
  type            DeliverabilityEventType
  subtype         String                  @default("") // DSN/bounce reason code, etc.
  provider        String                  @default("")
  meta            String                  @default("")
  occurredAt      DateTime                @default(now())

  inbox         Inbox?         @relation(fields: [inboxId], references: [id], onDelete: SetNull)
  sendingDomain SendingDomain? @relation(fields: [sendingDomainId], references: [id], onDelete: SetNull)

  @@index([inboxId])
  @@index([sendingDomainId])
  @@index([campaignId])
  @@index([type])
  @@index([occurredAt])
}

/// An inbox-placement (seed) test result — the ONLY trustworthy "are we in the
/// inbox?" signal (send logs only prove "not bounced"). Manual entry now; a
/// GlockApps/MailReach API can write the same rows later.
model PlacementTest {
  id              String            @id @default(cuid())
  sendingDomainId String
  campaignId      String?
  provider        PlacementProvider @default(MANUAL_SEED)
  inboxPct        Float             @default(0)
  spamPct         Float             @default(0)
  promotionsPct   Float             @default(0)
  missingPct      Float             @default(0)
  seedCount       Int               @default(0)
  note            String            @default("")
  runAt           DateTime          @default(now())

  sendingDomain SendingDomain @relation(fields: [sendingDomainId], references: [id], onDelete: Cascade)

  @@index([sendingDomainId])
  @@index([runAt])
}

/// Precomputed daily rollup for a scope. Rates are DERIVED (lib/coldemail/analytics.ts),
/// not stored. `opens` is retained but treated as UNRELIABLE (MPP-inflated) — never
/// a health signal. Upserted by the rollup sweep, keyed by (scope, scopeId, date).
model MetricsDaily {
  id              String       @id @default(cuid())
  date            DateTime // UTC day
  scope           MetricsScope
  scopeId         String
  sent            Int          @default(0)
  delivered       Int          @default(0)
  hardBounce      Int          @default(0)
  softBounce      Int          @default(0)
  opens           Int          @default(0) // UNRELIABLE — MPP/scanner inflated
  uniqueClicks    Int          @default(0)
  replies         Int          @default(0)
  positiveReplies Int          @default(0)
  complaints      Int          @default(0)
  unsubscribes    Int          @default(0)
  updatedAt       DateTime     @updatedAt

  @@unique([scope, scopeId, date])
  @@index([scope, scopeId])
  @@index([date])
}

/// A health snapshot feeding auto-pause. `triggeredRules` is a comma-separated
/// list of the rule keys that fired (bounce_pause_inbox, complaint_pause_domain…).
model HealthSnapshot {
  id             String       @id @default(cuid())
  date           DateTime // UTC day
  scope          MetricsScope
  scopeId        String
  healthScore    Int          @default(100)
  status         HealthStatus @default(HEALTHY)
  bounceRate     Float        @default(0)
  complaintRate  Float        @default(0)
  triggeredRules String       @default("")
  createdAt      DateTime     @default(now())

  @@unique([scope, scopeId, date])
  @@index([scope, scopeId])
  @@index([date])
}

