import { test } from "node:test";
import assert from "node:assert/strict";
import {
  WARMUP_PRESETS,
  normalizePlan,
  warmupDailyLimit,
  isWarmupComplete,
  applyHealthBackoff,
  inboxAllowedVolume,
  warmupRampCurve,
  warmupStatus,
} from "../lib/coldemail/warmup.ts";
import {
  remainingCapacity,
  isInboxEligible,
  selectNextInbox,
  planRotation,
  bounceRate,
  complaintRate,
  resolveThresholds,
  evaluateInboxAutoPause,
  evaluateDomainAutoPause,
  DEFAULT_THRESHOLDS,
  type RotationInbox,
} from "../lib/coldemail/rotation.ts";
import {
  deriveRates,
  addCounts,
  ZERO_COUNTS,
  bounceBand,
  complaintBand,
  placementBand,
  healthScore,
  healthLevel,
  normalizePlacement,
  OPEN_RATE_UNRELIABLE,
  formatPct,
  type MetricCounts,
} from "../lib/coldemail/analytics.ts";

// ===========================================================================
// Warmup ramp math
// ===========================================================================

test("warmupDailyLimit starts at startCap on day 0 and reaches targetCap at rampDays", () => {
  const plan = { startCap: 5, targetCap: 40, rampDays: 20 };
  assert.equal(warmupDailyLimit(0, plan), 5);
  assert.equal(warmupDailyLimit(20, plan), 40);
  assert.equal(warmupDailyLimit(100, plan), 40); // clamps past the ramp
  // Midpoint is between start and target and monotonically increasing.
  const mid = warmupDailyLimit(10, plan);
  assert.ok(mid > 5 && mid < 40, `midpoint ${mid} should be strictly between`);
});

test("warmupDailyLimit is monotonically non-decreasing across the ramp", () => {
  const plan = WARMUP_PRESETS.STANDARD;
  let prev = 0;
  for (let d = 0; d <= plan.rampDays + 3; d++) {
    const v = warmupDailyLimit(d, plan);
    assert.ok(v >= prev, `day ${d}: ${v} < prev ${prev}`);
    prev = v;
  }
});

test("normalizePlan clamps bad input so a ramp is never uncapped", () => {
  const p = normalizePlan({ startCap: -5, targetCap: 0, rampDays: 0 });
  assert.ok(p.startCap >= 1);
  assert.ok(p.targetCap >= p.startCap);
  assert.ok(p.rampDays >= 1);
  // A negative day floors to startCap, never a negative/huge number.
  assert.equal(warmupDailyLimit(-3, p), p.startCap);
});

test("isWarmupComplete flips exactly at rampDays", () => {
  const plan = { startCap: 5, targetCap: 40, rampDays: 14 };
  assert.equal(isWarmupComplete(13, plan), false);
  assert.equal(isWarmupComplete(14, plan), true);
  assert.equal(isWarmupComplete(99, plan), true);
});

test("applyHealthBackoff shrinks volume for unhealthy inboxes (adaptive)", () => {
  assert.equal(applyHealthBackoff(40, 90), 40); // healthy: unchanged
  assert.equal(applyHealthBackoff(40, 70), 20); // degraded: halved
  assert.equal(applyHealthBackoff(40, 30), 10); // danger: quartered
  assert.ok(applyHealthBackoff(1, 0) >= 1); // never below 1
});

test("inboxAllowedVolume clamps the ramp by the absolute dailyCap", () => {
  const start = new Date("2026-01-01T00:00:00Z");
  const now = new Date("2026-01-31T00:00:00Z"); // 30 days in → ramp complete
  const v = inboxAllowedVolume({
    warmupStartedAt: start,
    plan: { startCap: 5, targetCap: 40, rampDays: 21 },
    dailyCap: 25,
    now,
  });
  assert.equal(v, 25, "target 40 must be clamped to the 25 dailyCap");
});

test("inboxAllowedVolume with null warmupStartedAt is day 0 (startCap), never uncapped", () => {
  const v = inboxAllowedVolume({ warmupStartedAt: null, plan: WARMUP_PRESETS.STANDARD, dailyCap: 40 });
  assert.equal(v, WARMUP_PRESETS.STANDARD.startCap);
});

test("warmupRampCurve spans day 0..rampDays and ends at targetCap", () => {
  const plan = { startCap: 5, targetCap: 30, rampDays: 10 };
  const curve = warmupRampCurve(plan);
  assert.equal(curve.length, 11);
  assert.equal(curve[0].planned, 5);
  assert.equal(curve[curve.length - 1].planned, 30);
});

test("warmupStatus produces a plain-language, 1-based label", () => {
  const s = warmupStatus(8, { startCap: 5, targetCap: 40, rampDays: 21 });
  assert.equal(s.complete, false);
  assert.match(s.label, /day 9 of 21/);
  const done = warmupStatus(30, { startCap: 5, targetCap: 40, rampDays: 21 });
  assert.equal(done.complete, true);
  assert.match(done.label, /Warmed/);
});

// ===========================================================================
// Rotation
// ===========================================================================

const inbox = (over: Partial<RotationInbox>): RotationInbox => ({
  id: "i",
  status: "ACTIVE",
  allowedToday: 40,
  sentToday: 0,
  authGreen: true,
  lastSendAt: null,
  minGapSeconds: 0,
  ...over,
});

test("remainingCapacity never goes negative", () => {
  assert.equal(remainingCapacity(inbox({ allowedToday: 10, sentToday: 4 })), 6);
  assert.equal(remainingCapacity(inbox({ allowedToday: 10, sentToday: 25 })), 0);
});

test("isInboxEligible enforces status, auth, capacity and the min gap", () => {
  const now = Date.UTC(2026, 0, 1, 12, 0, 0);
  assert.equal(isInboxEligible(inbox({}), now).eligible, true);
  assert.equal(isInboxEligible(inbox({ status: "WARMING" }), now).eligible, false);
  assert.equal(isInboxEligible(inbox({ status: "PAUSED" }), now).eligible, false);
  assert.equal(isInboxEligible(inbox({ authGreen: false }), now).eligible, false);
  assert.equal(isInboxEligible(inbox({ allowedToday: 5, sentToday: 5 }), now).eligible, false);
  // Sent 30s ago with a 100s gap → not yet eligible.
  const recent = new Date(now - 30_000);
  assert.equal(isInboxEligible(inbox({ minGapSeconds: 100, lastSendAt: recent }), now).eligible, false);
  // Sent 200s ago with a 100s gap → eligible.
  const older = new Date(now - 200_000);
  assert.equal(isInboxEligible(inbox({ minGapSeconds: 100, lastSendAt: older }), now).eligible, true);
});

test("selectNextInbox rotates to the least-recently-used eligible inbox", () => {
  const now = Date.UTC(2026, 0, 1, 12, 0, 0);
  const a = inbox({ id: "a", lastSendAt: new Date(now - 500_000) });
  const b = inbox({ id: "b", lastSendAt: new Date(now - 900_000) }); // oldest
  const c = inbox({ id: "c", status: "PAUSED" });
  const picked = selectNextInbox([a, b, c], now);
  assert.equal(picked?.id, "b");
});

test("selectNextInbox returns null when nothing is eligible", () => {
  const now = Date.now();
  assert.equal(selectNextInbox([inbox({ status: "BURNING" }), inbox({ authGreen: false })], now), null);
});

test("planRotation spreads sends across inboxes by capacity, honouring caps", () => {
  const a = inbox({ id: "a", allowedToday: 3, sentToday: 0 });
  const b = inbox({ id: "b", allowedToday: 2, sentToday: 0 });
  const order = planRotation([a, b], 10);
  // Only 5 total capacity exists → only 5 assignments.
  assert.equal(order.length, 5);
  const counts = order.reduce<Record<string, number>>((m, id) => ((m[id] = (m[id] ?? 0) + 1), m), {});
  assert.equal(counts.a, 3);
  assert.equal(counts.b, 2);
  // First pick is the higher-capacity inbox.
  assert.equal(order[0], "a");
});

test("planRotation excludes paused/unauthenticated inboxes", () => {
  const good = inbox({ id: "g", allowedToday: 5 });
  const paused = inbox({ id: "p", status: "PAUSED", allowedToday: 5 });
  const order = planRotation([good, paused], 10);
  assert.ok(order.every((id) => id === "g"));
  assert.equal(order.length, 5);
});

// ===========================================================================
// Auto-pause thresholds
// ===========================================================================

test("bounceRate and complaintRate divide safely", () => {
  assert.equal(bounceRate({ sent: 0, delivered: 0, bounces: 0, complaints: 0 }), 0);
  assert.equal(bounceRate({ sent: 100, delivered: 90, bounces: 3, complaints: 0 }), 0.03);
  assert.equal(complaintRate({ sent: 100, delivered: 100, bounces: 0, complaints: 1 }), 0.01);
  // complaint falls back to sent when delivered is 0.
  assert.equal(complaintRate({ sent: 100, delivered: 0, bounces: 0, complaints: 1 }), 0.01);
});

test("evaluateInboxAutoPause pauses an inbox at ~1.8% bounce", () => {
  const below = evaluateInboxAutoPause({ sent: 1000, delivered: 980, bounces: 17, complaints: 0 });
  assert.equal(below.pause, false); // 1.7%
  const at = evaluateInboxAutoPause({ sent: 1000, delivered: 980, bounces: 18, complaints: 0 });
  assert.equal(at.pause, true); // 1.8%
  assert.ok(at.rules.includes("bounce_pause_inbox"));
  const hard = evaluateInboxAutoPause({ sent: 1000, delivered: 900, bounces: 60, complaints: 0 });
  assert.equal(hard.pause, true);
  assert.equal(hard.hardStop, true); // 6% ≥ 5% hard stop
  assert.ok(hard.rules.includes("bounce_hard_stop"));
});

test("evaluateInboxAutoPause respects the minimum-sends guard", () => {
  // 2 of 5 bounced = 40% but volume is too low to judge.
  const v = evaluateInboxAutoPause({ sent: 5, delivered: 3, bounces: 2, complaints: 0 });
  assert.equal(v.pause, false);
  assert.equal(v.level, "healthy");
});

test("evaluateDomainAutoPause pauses a domain above 0.08% complaint", () => {
  // 1 complaint in 2000 delivered = 0.05% → warn only.
  const warn = evaluateDomainAutoPause({ sent: 2000, delivered: 2000, bounces: 0, complaints: 1 });
  assert.equal(warn.pause, false);
  assert.equal(warn.level, "warning");
  // 2 complaints in 2000 = 0.10% ≥ 0.08% → pause + flag targeting.
  const pause = evaluateDomainAutoPause({ sent: 2000, delivered: 2000, bounces: 0, complaints: 2 });
  assert.equal(pause.pause, true);
  assert.ok(pause.rules.includes("complaint_pause_domain"));
});

test("evaluateDomainAutoPause pauses a domain on sustained 2% bounce", () => {
  const v = evaluateDomainAutoPause({ sent: 1000, delivered: 970, bounces: 20, complaints: 0 });
  assert.equal(v.pause, true);
  assert.ok(v.rules.includes("bounce_pause_domain"));
});

test("resolveThresholds overlays valid overrides only", () => {
  const t = resolveThresholds({ bouncePauseInbox: 0.03, complaintPauseDomain: -1 as unknown as number });
  assert.equal(t.bouncePauseInbox, 0.03);
  assert.equal(t.complaintPauseDomain, DEFAULT_THRESHOLDS.complaintPauseDomain); // invalid override ignored
});

// ===========================================================================
// Analytics rate derivation + open-rate honesty
// ===========================================================================

test("deriveRates computes every rate over the right denominator", () => {
  const m: MetricCounts = {
    sent: 1000,
    delivered: 950,
    hardBounce: 30,
    softBounce: 20,
    opens: 600,
    uniqueClicks: 95,
    replies: 38,
    positiveReplies: 19,
    complaints: 1,
    unsubscribes: 19,
  };
  const r = deriveRates(m);
  assert.equal(r.deliveryRate, 0.95); // 950/1000
  assert.equal(r.bounceRate, 0.05); // (30+20)/1000
  assert.equal(r.hardBounceRate, 0.03);
  assert.equal(Math.round(r.replyRate * 1000) / 1000, 0.04); // 38/950
  assert.equal(r.clickRate, 0.1); // 95/950
  assert.equal(r.complaintRate, 1 / 950);
});

test("deriveRates never returns NaN on empty input", () => {
  const r = deriveRates(ZERO_COUNTS);
  for (const v of Object.values(r)) assert.equal(Number.isNaN(v), false);
});

test("addCounts sums buckets field-by-field", () => {
  const a = { ...ZERO_COUNTS, sent: 10, replies: 1 };
  const b = { sent: 5, replies: 2, complaints: 1 };
  const sum = addCounts(a, b);
  assert.equal(sum.sent, 15);
  assert.equal(sum.replies, 3);
  assert.equal(sum.complaints, 1);
});

test("open rate is flagged unreliable and excluded from the health score", () => {
  assert.equal(OPEN_RATE_UNRELIABLE, true);
  // Two identical count sets that differ ONLY in opens must score identically —
  // proving opens are NOT a health input (the whole 2026 honesty point).
  const base: MetricCounts = { ...ZERO_COUNTS, sent: 500, delivered: 490, replies: 15 };
  const inflated: MetricCounts = { ...base, opens: 480 };
  assert.equal(healthScore(base), healthScore(inflated));
});

test("healthScore punishes complaints hardest and rewards replies", () => {
  const clean: MetricCounts = { ...ZERO_COUNTS, sent: 1000, delivered: 990, replies: 30 };
  const complained: MetricCounts = { ...ZERO_COUNTS, sent: 1000, delivered: 990, complaints: 3 };
  assert.ok(healthScore(clean) > healthScore(complained));
  assert.ok(healthScore(complained) < 80);
  assert.equal(healthScore(ZERO_COUNTS), 100); // no volume → no judgement
});

test("benchmark bands match research §4", () => {
  assert.equal(bounceBand(0.01), "green");
  assert.equal(bounceBand(0.03), "amber");
  assert.equal(bounceBand(0.06), "red");
  assert.equal(complaintBand(0.0003), "green");
  assert.equal(complaintBand(0.0006), "amber");
  assert.equal(complaintBand(0.001), "red");
  assert.equal(placementBand(0.95), "green");
  assert.equal(placementBand(0.85), "amber");
  assert.equal(placementBand(0.7), "red");
});

test("normalizePlacement accepts whole-percent inputs and clamps", () => {
  const p = normalizePlacement({ inboxPct: 90, spamPct: 8, promotionsPct: 2, missingPct: 0 });
  assert.equal(p.inboxPct, 0.9);
  assert.equal(p.spamPct, 0.08);
});

test("healthLevel + formatPct format for the UI", () => {
  assert.equal(healthLevel(90), "healthy");
  assert.equal(healthLevel(60), "warning");
  assert.equal(healthLevel(20), "danger");
  assert.equal(formatPct(0.0123), "1.23%");
  assert.equal(formatPct(NaN), "—");
});

