import { buildMessage, getTransport, type SendIdentity, type MailTransport } from "../lib/coldemail/sender";
import { inboxAllowedVolume } from "../lib/coldemail/warmup";
import { selectNextInbox, type RotationInbox } from "../lib/coldemail/rotation";
import { logEvent } from "../lib/log";

/**
 * A brand's rotation pool for this sweep: the ACTIVE inboxes on its authenticated
 * domains, each with the send identity + today's warmup-clamped allowance and the
 * live rotation candidate the selector mutates as sends go out.
 */
type PoolInbox = {
  candidate: RotationInbox;
  identity: SendIdentity;
  sendingDomainId: string;
};

/**
 * Load a brand's rotation pool. Returns [] when the brand has no inboxes — the
 * worker then falls back to the Phase 2 brand-level cap path unchanged. Only
 * inboxes on a domain with SPF+DKIM+DMARC all verified are authenticated (authGreen).
 */
async function loadBrandRotationPool(brandId: string, brand: SendIdentity, now: Date): Promise<PoolInbox[]> {
  let inboxes;
  try {
    inboxes = await db.inbox.findMany({
      where: { status: "ACTIVE", sendingDomain: { brandId } },
      include: { sendingDomain: true },
    });
  } catch {
    return []; // tables not migrated on this env — behave like Phase 2
  }
  if (inboxes.length === 0) return [];

  const dayStart = startOfUtcDay(now);
  const pool: PoolInbox[] = [];
  for (const ib of inboxes) {
    const d = ib.sendingDomain;
    const authGreen = !!(d?.spfVerified && d?.dkimVerified && d?.dmarcVerified);
    const allowedToday = inboxAllowedVolume({
      warmupStartedAt: ib.warmupStartedAt,
      plan: { startCap: ib.startCap, targetCap: ib.targetCap, rampDays: ib.rampDays },
      dailyCap: ib.dailyCap,
      healthScore: ib.healthScore,
      adaptive: ib.strategy === "ADAPTIVE",
      now,
    });
    const sentToday = await db.coldSend.count({ where: { inboxId: ib.id, sentAt: { gte: dayStart } } });
    pool.push({
      sendingDomainId: ib.sendingDomainId,
      candidate: {
        id: ib.id,
        status: ib.status as RotationInbox["status"],
        allowedToday,
        sentToday,
        authGreen,
        lastSendAt: ib.lastSendAt,
        minGapSeconds: ib.minGapSeconds,
      },
      // Send AS the inbox address, keeping the brand's name/postal/reply-to. This is
      // what makes rotation real — each message goes out from a different mailbox.
      identity: {
        ...brand,
        fromEmail: ib.email,
        sendingDomain: d ? `${d.subdomain ? d.subdomain + "." : ""}${d.domain}` : brand.sendingDomain,
      },
    });
  }
  return pool;
}

/** Append a deliverability event (the analytics spine). Never throws to the caller. */
async function recordDeliverability(
  type: "SENT" | "FAILED" | "DELIVERED",
  ctx: { inboxId?: string | null; sendingDomainId?: string | null; campaignId: string; contactId?: string | null; sendId: string; meta?: string },
): Promise<void> {
  const t = type === "FAILED" ? "DEFERRED" : type; // FAILED maps to a soft/deferred signal
  try {
    await db.deliverabilityEvent.create({
      data: {
        type: t,
        inboxId: ctx.inboxId ?? null,
        sendingDomainId: ctx.sendingDomainId ?? null,
        campaignId: ctx.campaignId,
        contactId: ctx.contactId ?? null,
        sendId: ctx.sendId,
        meta: (ctx.meta ?? "").slice(0, 300),
      },
    });
  } catch {
    /* table not migrated / best-effort — analytics must never fail a send */
  }
}

