// Cold Email Engine — warmup + deliverability rollup / auto-pause sweeps (Phase 3).
//
// Two background passes, both safe to run regardless of the send kill-switch
// because NEITHER sends mail — they maintain warmup state and roll DeliverabilityEvent
// rows into MetricsDaily / HealthSnapshot, then AUTO-PAUSE inboxes/domains whose
// bounce or complaint rate crossed a burn threshold (research §4). All queries are
// tolerant of un-migrated tables (mirrors the send sweep).

import { db } from "../lib/db";
import { getSetting } from "../lib/settings";
import { logEvent } from "../lib/log";
import { inboxAllowedVolume, warmupStatus } from "../lib/coldemail/warmup";
import { warmupDayIndex } from "../lib/coldemail/compliance";
import {
  resolveThresholds,
  evaluateInboxAutoPause,
  evaluateDomainAutoPause,
  bounceRate,
  complaintRate,
  type BurnThresholds,
  type RateStats,
} from "../lib/coldemail/rotation";
import { addCounts, deriveRates, healthScore, healthLevel, ZERO_COUNTS, type MetricCounts } from "../lib/coldemail/analytics";

function startOfUtcDay(now = new Date()): Date {
  return new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
}

// ---------------------------------------------------------------------------
// Warmup sweep — recompute each inbox's ramp cap + today's WarmupState, and
// promote a fully-warmed, authenticated inbox from WARMING → ACTIVE.
// ---------------------------------------------------------------------------

export async function coldEmailWarmupSweep(): Promise<void> {
  let inboxes;
  try {
    inboxes = await db.inbox.findMany({
      where: { status: { in: ["WARMING", "ACTIVE"] } },
      include: { sendingDomain: { select: { spfVerified: true, dkimVerified: true, dmarcVerified: true } } },
    });
  } catch {
    return; // tables not migrated on this env
  }

  const now = new Date();
  const day0 = startOfUtcDay(now);

  for (const ib of inboxes) {
    const plan = { startCap: ib.startCap, targetCap: ib.targetCap, rampDays: ib.rampDays };
    const day = warmupDayIndex(ib.warmupStartedAt, now);
    const status = warmupStatus(day, plan);
    const currentRampCap = inboxAllowedVolume({
      warmupStartedAt: ib.warmupStartedAt,
      plan,
      dailyCap: ib.dailyCap,
      healthScore: ib.healthScore,
      adaptive: ib.strategy === "ADAPTIVE",
      now,
    });

    try {
      await db.inbox.update({ where: { id: ib.id }, data: { warmupDay: day, currentRampCap } });

      // Actual sends made by this inbox today (for the planned-vs-actual curve).
      const sentVolume = await db.coldSend.count({ where: { inboxId: ib.id, sentAt: { gte: day0 } } });
      await db.warmupState.upsert({
        where: { inboxId_date: { inboxId: ib.id, date: day0 } },
        create: {
          inboxId: ib.id,
          date: day0,
          day,
          plannedVolume: currentRampCap,
          sentVolume,
          healthScore: ib.healthScore,
        },
        update: { day, plannedVolume: currentRampCap, sentVolume, healthScore: ib.healthScore },
      });

      // Promote a warmed + authenticated inbox to ACTIVE (rotation-eligible). We only
      // auto-promote; we never auto-pause here (that's the rollup sweep's job).
      const d = ib.sendingDomain;
      const authGreen = !!(d?.spfVerified && d?.dkimVerified && d?.dmarcVerified);
      if (ib.status === "WARMING" && status.complete && authGreen) {
        await db.inbox.update({ where: { id: ib.id }, data: { status: "ACTIVE", pausedReason: "" } });
        await logEvent("info", "coldemail.warmup.complete", { inboxId: ib.id, day });
      }
    } catch (err) {
      await logEvent("error", "coldemail.warmup.sweep", { inboxId: ib.id, message: String(err) });
    }
  }
}

// ---------------------------------------------------------------------------
// Rollup + auto-pause sweep
// ---------------------------------------------------------------------------

const EVENT_TO_COUNT: Record<string, Partial<MetricCounts>> = {
  SENT: { sent: 1 },
  DELIVERED: { delivered: 1 },
  HARD_BOUNCE: { hardBounce: 1 },
  SOFT_BOUNCE: { softBounce: 1 },
  OPEN: { opens: 1 },
  CLICK: { uniqueClicks: 1 },
  REPLY: { replies: 1 },
  POSITIVE_REPLY: { positiveReplies: 1, replies: 1 },
  COMPLAINT: { complaints: 1 },
  UNSUBSCRIBE: { unsubscribes: 1 },
};

type Grouped = Map<string, MetricCounts>;

function bump(map: Grouped, key: string | null | undefined, delta: Partial<MetricCounts>): void {
  if (!key) return;
  map.set(key, addCounts(map.get(key) ?? ZERO_COUNTS, delta));
}

async function upsertMetrics(scope: "INBOX" | "DOMAIN" | "CAMPAIGN" | "BRAND", date: Date, map: Grouped): Promise<void> {
  for (const [scopeId, c] of map) {
    await db.metricsDaily
      .upsert({
        where: { scope_scopeId_date: { scope, scopeId, date } },
        create: { scope, scopeId, date, ...c },
        update: { ...c },
      })
      .catch(() => null);
  }
}

/** Aggregate this UTC day's DeliverabilityEvent rows into MetricsDaily by scope. */
export async function coldEmailRollupSweep(): Promise<void> {
  const now = new Date();
  const day0 = startOfUtcDay(now);

  let events;
  try {
    events = await db.deliverabilityEvent.findMany({
      where: { occurredAt: { gte: day0 } },
      select: { type: true, inboxId: true, sendingDomainId: true, campaignId: true },
    });
  } catch {
    return; // not migrated
  }

  const byInbox: Grouped = new Map();
  const byDomain: Grouped = new Map();
  const byCampaign: Grouped = new Map();
  const brandByDomain = new Map<string, string>();

  for (const e of events) {
    const delta = EVENT_TO_COUNT[e.type];
    if (!delta) continue;
    bump(byInbox, e.inboxId, delta);
    bump(byDomain, e.sendingDomainId, delta);
    bump(byCampaign, e.campaignId, delta);
  }

  try {
    await upsertMetrics("INBOX", day0, byInbox);
    await upsertMetrics("DOMAIN", day0, byDomain);
    await upsertMetrics("CAMPAIGN", day0, byCampaign);
  } catch (err) {
    await logEvent("error", "coldemail.rollup.upsert", { message: String(err) });
  }

  // Roll domains up to their brand for the agency/multi-client view.
  const byBrand: Grouped = new Map();
  for (const [domainId, c] of byDomain) {
    let brandId = brandByDomain.get(domainId);
    if (!brandId) {
      const d = await db.sendingDomain.findUnique({ where: { id: domainId }, select: { brandId: true } }).catch(() => null);
      brandId = d?.brandId;
      if (brandId) brandByDomain.set(domainId, brandId);
    }
    if (brandId) bump(byBrand, brandId, c);
  }
  await upsertMetrics("BRAND", day0, byBrand).catch(() => null);

  // Auto-pause pass over the trailing window.
  const thresholds = await loadThresholds();
  await evaluateInboxes(thresholds);
  await evaluateDomains(thresholds);
}

async function loadThresholds(): Promise<BurnThresholds> {
  const num = async (key: string) => {
    const v = Number(await getSetting(key));
    return Number.isFinite(v) && v > 0 ? v : undefined;
  };
  return resolveThresholds({
    bouncePauseInbox: await num("coldemail_bounce_pause_inbox"),
    bouncePauseDomain: await num("coldemail_bounce_pause_domain"),
    bounceHardStop: await num("coldemail_bounce_hard_stop"),
    complaintPauseDomain: await num("coldemail_complaint_pause_domain"),
  });
}

/** RateStats for a scope over a trailing window (default 7 days). */
async function statsForScope(where: Record<string, unknown>, sinceDays = 7): Promise<RateStats> {
  const since = new Date(Date.now() - sinceDays * 86_400_000);
  const rows = await db.deliverabilityEvent
    .groupBy({ by: ["type"], where: { ...where, occurredAt: { gte: since } }, _count: { _all: true } })
    .catch(() => [] as { type: string; _count: { _all: number } }[]);
  let sent = 0,
    delivered = 0,
    bounces = 0,
    complaints = 0;
  for (const r of rows as { type: string; _count: { _all: number } }[]) {
    const n = r._count._all;
    if (r.type === "SENT") sent += n;
    else if (r.type === "DELIVERED") delivered += n;
    else if (r.type === "HARD_BOUNCE" || r.type === "SOFT_BOUNCE") bounces += n;
    else if (r.type === "COMPLAINT") complaints += n;
  }
  return { sent, delivered, bounces, complaints };
}

async function writeHealthSnapshot(scope: "INBOX" | "DOMAIN", scopeId: string, stats: RateStats, rules: string[], paused: boolean): Promise<void> {
  const day0 = startOfUtcDay();
  const counts: MetricCounts = { ...ZERO_COUNTS, sent: stats.sent, delivered: stats.delivered, hardBounce: stats.bounces, complaints: stats.complaints };
  const score = healthScore(counts);
  const status = paused ? "PAUSED" : healthLevel(score) === "healthy" ? "HEALTHY" : healthLevel(score) === "warning" ? "WARNING" : "DANGER";
  await db.healthSnapshot
    .upsert({
      where: { scope_scopeId_date: { scope, scopeId, date: day0 } },
      create: { scope, scopeId, date: day0, healthScore: score, status, bounceRate: bounceRate(stats), complaintRate: complaintRate(stats), triggeredRules: rules.join(",") },
      update: { healthScore: score, status, bounceRate: bounceRate(stats), complaintRate: complaintRate(stats), triggeredRules: rules.join(",") },
    })
    .catch(() => null);
}

async function evaluateInboxes(thresholds: BurnThresholds): Promise<void> {
  let inboxes;
  try {
    inboxes = await db.inbox.findMany({ where: { status: "ACTIVE" }, select: { id: true } });
  } catch {
    return;
  }
  for (const ib of inboxes) {
    const stats = await statsForScope({ inboxId: ib.id });
    const v = evaluateInboxAutoPause(stats, thresholds);
    await writeHealthSnapshot("INBOX", ib.id, stats, v.rules, v.pause);
    if (v.pause) {
      await db.inbox
        .update({ where: { id: ib.id }, data: { status: v.hardStop ? "BURNING" : "PAUSED", pausedReason: v.reasons.join("; ").slice(0, 400) } })
        .catch(() => null);
      await logEvent("warn", "coldemail.autopause.inbox", { inboxId: ib.id, rules: v.rules, bounceRate: bounceRate(stats) });
    }
  }
}

async function evaluateDomains(thresholds: BurnThresholds): Promise<void> {
  let domains;
  try {
    domains = await db.sendingDomain.findMany({ where: { status: { in: ["ACTIVE", "WARMING"] } }, select: { id: true } });
  } catch {
    return;
  }
  for (const d of domains) {
    const stats = await statsForScope({ sendingDomainId: d.id });
    const v = evaluateDomainAutoPause(stats, thresholds);
    await writeHealthSnapshot("DOMAIN", d.id, stats, v.rules, v.pause);
    if (v.pause) {
      await db.sendingDomain
        .update({ where: { id: d.id }, data: { status: v.hardStop ? "BURNED" : "PAUSED", pausedReason: v.reasons.join("; ").slice(0, 400) } })
        .catch(() => null);
      // Take the domain's inboxes out of rotation too.
      await db.inbox.updateMany({ where: { sendingDomainId: d.id, status: "ACTIVE" }, data: { status: "PAUSED", pausedReason: "Domain auto-paused" } }).catch(() => null);
      await logEvent("warn", "coldemail.autopause.domain", { domainId: d.id, rules: v.rules, complaintRate: complaintRate(stats), bounceRate: bounceRate(stats) });
    }
  }
}

