const DOMAIN_RE = /^[a-z0-9.-]+\.[a-z]{2,}$/;
const PROVIDERS = ["GMAIL", "M365", "SMTP", "POSTAL", "KUMO"] as const;
const STRATEGIES = ["CONSERVATIVE", "STANDARD", "AGGRESSIVE", "ADAPTIVE"] as const;
const MODES = ["POOL", "REAL_SEED", "HYBRID"] as const;
const DMARC_POLICIES = ["NONE", "QUARANTINE", "REJECT"] as const;

function pick<T extends readonly string[]>(list: T, raw: unknown, fallback: T[number]): T[number] {
  const v = String(raw ?? "").toUpperCase();
  return (list as readonly string[]).includes(v) ? (v as T[number]) : fallback;
}

// ---------------------------------------------------------------------------
// Sending domains
// ---------------------------------------------------------------------------

/** Create or update a dedicated sending domain for a brand. */
export async function saveSendingDomain(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const id = String(formData.get("id") ?? "").trim() || null;
  const brandId = String(formData.get("brandId") ?? "").trim();
  const domain = normalizeDomain(String(formData.get("domain") ?? ""));
  const subdomain = normalizeDomain(String(formData.get("subdomain") ?? "mail")).replace(/\..*$/, "") || "mail";
  const trackingDomain = normalizeDomain(String(formData.get("trackingDomain") ?? ""));
  const isPrimary = formData.get("isPrimary") === "on" || formData.get("isPrimary") === "true";

  if (!brandId) return { error: "Pick a brand." };
  if (!domain || !DOMAIN_RE.test(domain)) return { error: "Enter a valid apex domain (e.g. try-brand.com)." };
  if (trackingDomain && !DOMAIN_RE.test(trackingDomain)) return { error: "Tracking domain must be a valid domain or blank." };
  const brand = await db.brand.findUnique({ where: { id: brandId }, select: { id: true } });
  if (!brand) return { error: "Brand not found." };

  try {
    if (id) {
      await db.sendingDomain.update({ where: { id }, data: { domain, subdomain, trackingDomain, isPrimary } });
    } else {
      await db.sendingDomain.create({ data: { brandId, domain, subdomain, trackingDomain, isPrimary } });
    }
  } catch (err) {
    await logEvent("error", "coldemail.domain.save", { message: String(err) });
    return { error: "Could not save the domain (is it already registered for this brand?)." };
  }
  revalidatePath("/admin/coldemail/domains");
  revalidatePath("/admin/coldemail/analytics");
  return { ok: true };
}

/**
 * Set a domain's authentication + tracking verification flags and DMARC policy.
 * Config-only (no live DNS check yet). Auto-advances PENDING → WARMING once SPF +
 * DKIM + DMARC are all green, and stamps warmupStartedAt so its inboxes can ramp.
 */
export async function setDomainVerification(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const id = String(formData.get("id") ?? "").trim();
  if (!id) return { error: "Missing domain." };
  const spfVerified = formData.get("spfVerified") === "on" || formData.get("spfVerified") === "true";
  const dkimVerified = formData.get("dkimVerified") === "on" || formData.get("dkimVerified") === "true";
  const dmarcVerified = formData.get("dmarcVerified") === "on" || formData.get("dmarcVerified") === "true";
  const trackingDomainVerified = formData.get("trackingDomainVerified") === "on" || formData.get("trackingDomainVerified") === "true";
  const dmarcPolicy = pick(DMARC_POLICIES, formData.get("dmarcPolicy"), "NONE");

  const domain = await db.sendingDomain.findUnique({ where: { id }, select: { status: true, warmupStartedAt: true } });
  if (!domain) return { error: "Domain not found." };

  const authed = spfVerified && dkimVerified && dmarcVerified;
  const nextStatus = domain.status === "PENDING" && authed ? "WARMING" : domain.status;
  await db.sendingDomain.update({
    where: { id },
    data: {
      spfVerified,
      dkimVerified,
      dmarcVerified,
      trackingDomainVerified,
      dmarcPolicy,
      status: nextStatus,
      lastCheckedAt: new Date(),
      warmupStartedAt: authed ? domain.warmupStartedAt ?? new Date() : domain.warmupStartedAt,
    },
  });
  revalidatePath("/admin/coldemail/domains");
  return { ok: true };
}

/** Pause / resume / retire a domain. Resuming clears the pause reason. */
export async function setDomainStatus(id: string, status: "ACTIVE" | "PAUSED" | "WARMING" | "BURNED"): Promise<ActionState> {
  await requireArea("platform");
  await db.sendingDomain
    .update({ where: { id }, data: { status, pausedReason: status === "PAUSED" || status === "BURNED" ? "Paused by operator" : "" } })
    .catch(() => null);
  revalidatePath("/admin/coldemail/domains");
  return { ok: true };
}

export async function deleteSendingDomain(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.sendingDomain.delete({ where: { id } }).catch(() => null);
  revalidatePath("/admin/coldemail/domains");
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Inboxes
// ---------------------------------------------------------------------------

const capInt = (raw: unknown, lo: number, hi: number, fb: number) => {
  const n = Math.floor(Number(raw));
  return Number.isFinite(n) ? Math.min(hi, Math.max(lo, n)) : fb;
};

/** Create or update a mailbox on a sending domain, with its warmup plan. */
export async function saveInbox(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const id = String(formData.get("id") ?? "").trim() || null;
  const sendingDomainId = String(formData.get("sendingDomainId") ?? "").trim();
  const email = normalizeEmail(String(formData.get("email") ?? ""));
  const provider = pick(PROVIDERS, formData.get("provider"), "SMTP");
  const strategy = pick(STRATEGIES, formData.get("strategy"), "STANDARD") as WarmupStrategyKey;
  const warmupMode = pick(MODES, formData.get("warmupMode"), "HYBRID");

  if (!sendingDomainId) return { error: "Pick a sending domain." };
  if (!email || !emailSchema.safeParse(email).success) return { error: "Enter a valid mailbox address." };
  const domain = await db.sendingDomain.findUnique({ where: { id: sendingDomainId }, select: { id: true } });
  if (!domain) return { error: "Sending domain not found." };

  // Warmup plan: default to the strategy preset, allow explicit overrides.
  const preset = WARMUP_PRESETS[strategy];
  const plan = normalizePlan({
    startCap: capInt(formData.get("startCap"), 1, 200, preset.startCap),
    targetCap: capInt(formData.get("targetCap"), 1, 500, preset.targetCap),
    rampDays: capInt(formData.get("rampDays"), 1, 90, preset.rampDays),
  });
  const dailyCap = capInt(formData.get("dailyCap"), 1, 500, plan.targetCap);
  const minGapSeconds = capInt(formData.get("minGapSeconds"), 30, 3600, 100);

  const data = {
    sendingDomainId,
    email,
    provider,
    strategy,
    warmupMode,
    startCap: plan.startCap,
    targetCap: plan.targetCap,
    rampDays: plan.rampDays,
    dailyCap,
    minGapSeconds,
  };
  try {
    if (id) {
      await db.inbox.update({ where: { id }, data });
    } else {
      await db.inbox.create({ data: { ...data, status: "WARMING", currentRampCap: plan.startCap } });
    }
  } catch (err) {
    await logEvent("error", "coldemail.inbox.save", { message: String(err) });
    return { error: "Could not save the inbox (is that address already registered?)." };
  }
  revalidatePath("/admin/coldemail/domains");
  revalidatePath("/admin/coldemail/warming");
  return { ok: true };
}

/** Begin (or restart) an inbox's warmup: stamp the start day and set it WARMING. */
export async function startInboxWarmup(id: string): Promise<ActionState> {
  await requireArea("platform");
  const ib = await db.inbox.findUnique({ where: { id }, select: { startCap: true } });
  if (!ib) return { error: "Inbox not found." };
  await db.inbox.update({
    where: { id },
    data: { warmupStartedAt: new Date(), warmupDay: 0, status: "WARMING", currentRampCap: ib.startCap, pausedReason: "" },
  });
  revalidatePath("/admin/coldemail/warming");
  revalidatePath("/admin/coldemail/domains");
  return { ok: true };
}

/** Pause / activate an inbox. Activation is an operator override (rotation still
 *  independently checks warmup + auth at send time). */
export async function setInboxStatus(id: string, status: "ACTIVE" | "PAUSED" | "WARMING"): Promise<ActionState> {
  await requireArea("platform");
  await db.inbox
    .update({ where: { id }, data: { status, pausedReason: status === "PAUSED" ? "Paused by operator" : "" } })
    .catch(() => null);
  revalidatePath("/admin/coldemail/warming");
  revalidatePath("/admin/coldemail/domains");
  return { ok: true };
}

export async function deleteInbox(id: string): Promise<ActionState> {
  await requireArea("platform");
  await db.inbox.delete({ where: { id } }).catch(() => null);
  revalidatePath("/admin/coldemail/domains");
  revalidatePath("/admin/coldemail/warming");
  return { ok: true };
}

// ---------------------------------------------------------------------------
// Placement (seed) tests + manual deliverability signals
// ---------------------------------------------------------------------------

/** Record a manual inbox-placement (seed) test result for a domain. */
export async function recordSeedResult(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const sendingDomainId = String(formData.get("sendingDomainId") ?? "").trim();
  if (!sendingDomainId) return { error: "Pick a domain." };
  const domain = await db.sendingDomain.findUnique({ where: { id: sendingDomainId }, select: { id: true } });
  if (!domain) return { error: "Domain not found." };

  const p = normalizePlacement({
    inboxPct: Number(formData.get("inboxPct")),
    spamPct: Number(formData.get("spamPct")),
    promotionsPct: Number(formData.get("promotionsPct")),
    missingPct: Number(formData.get("missingPct")),
  });
  const provider = pick(["GLOCKAPPS", "MAILREACH", "MANUAL_SEED"] as const, formData.get("provider"), "MANUAL_SEED");
  const seedCount = capInt(formData.get("seedCount"), 0, 10000, 0);
  const note = String(formData.get("note") ?? "").slice(0, 300);

  await db.placementTest.create({ data: { sendingDomainId, provider, ...p, seedCount, note } });
  await db.deliverabilityEvent
    .create({ data: { type: "PLACEMENT_TEST", sendingDomainId, provider, meta: `inbox ${(p.inboxPct * 100).toFixed(0)}%` } })
    .catch(() => null);
  revalidatePath("/admin/coldemail/analytics");
  revalidatePath("/admin/coldemail/domains");
  return { ok: true, error: `Recorded seed test — ${(p.inboxPct * 100).toFixed(0)}% inbox, ${(p.spamPct * 100).toFixed(0)}% spam.` };
}

/**
 * Record a manual deliverability signal (reply / positive reply / delivered /
 * hard-bounce / soft-bounce / complaint) into the analytics spine. Hard-bounce +
 * complaint additionally suppress the address via the existing feedback path.
 */
export async function recordDeliverabilitySignal(_prev: ActionState, formData: FormData): Promise<ActionState> {
  await requireArea("platform");
  const type = pick(
    ["REPLY", "POSITIVE_REPLY", "DELIVERED", "HARD_BOUNCE", "SOFT_BOUNCE", "COMPLAINT"] as const,
    formData.get("type"),
    "REPLY",
  );
  const email = normalizeEmail(String(formData.get("email") ?? ""));
  if (email && !emailSchema.safeParse(email).success) return { error: "Enter a valid email or leave it blank." };

  // Resolve the address to its latest send for attribution (best effort).
  let sendId: string | null = null;
  let campaignId: string | null = null;
  let inboxId: string | null = null;
  let sendingDomainId: string | null = null;
  if (email) {
    const contact = await db.contact.findUnique({ where: { email }, select: { id: true } });
    if (contact) {
      const last = await db.coldSend.findFirst({
        where: { contactId: contact.id },
        orderBy: { createdAt: "desc" },
        select: { id: true, campaignId: true, inboxId: true, inbox: { select: { sendingDomainId: true } } },
      });
      if (last) {
        sendId = last.id;
        campaignId = last.campaignId;
        inboxId = last.inboxId;
        sendingDomainId = last.inbox?.sendingDomainId ?? null;
      }
    }
  }

  await db.deliverabilityEvent
    .create({ data: { type, sendId, campaignId, inboxId, sendingDomainId, meta: "manual admin entry" } })
    .catch(() => null);

  // A hard bounce or complaint must also suppress — reuse the authoritative path.
  if (email && (type === "HARD_BOUNCE" || type === "COMPLAINT")) {
    await recordFeedback(email, type === "HARD_BOUNCE" ? "BOUNCE" : "COMPLAINT", { note: "manual deliverability entry" });
  }
  revalidatePath("/admin/coldemail/analytics");
  return { ok: true, error: `Recorded ${type.replace(/_/g, " ").toLowerCase()}.` };
}

