"use client";

import { useActionState, useEffect, useRef, useState, useTransition } from "react";
import {
  saveSendingDomain,
  setDomainVerification,
  setDomainStatus,
  deleteSendingDomain,
  saveInbox,
  startInboxWarmup,
  setInboxStatus,
  deleteInbox,
  recordSeedResult,
  recordDeliverabilitySignal,
} from "@/lib/actions-coldemail";

// Phase 3 admin controls: sending domains, inboxes, warmup, seed tests, and
// manual deliverability signals. Mirrors the Banner/useActionState pattern used
// by components/admin/coldemail/Controls.tsx.

type State = { error?: string; ok?: boolean };
const EMPTY: State = {};

function Banner({ state, okText }: { state: State; okText: string }) {
  if (state?.error) {
    const good = state.ok;
    return (
      <div
        className={`rounded-lg border px-3 py-2 text-sm ${
          good ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300" : "border-red-500/30 bg-red-500/10 text-red-400"
        }`}
      >
        {state.error}
      </div>
    );
  }
  if (state?.ok) {
    return (
      <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/10 px-3 py-2 text-sm text-emerald-300">{okText}</div>
    );
  }
  return null;
}

type Option = { id: string; label: string };

// ---------------------------------------------------------------------------
// Sending domains
// ---------------------------------------------------------------------------

export function SendingDomainForm({ brands }: { brands: Option[] }) {
  const [state, action, pending] = useActionState(saveSendingDomain, EMPTY);
  const ref = useRef<HTMLFormElement>(null);
  useEffect(() => {
    if (state?.ok) ref.current?.reset();
  }, [state]);
  return (
    <form ref={ref} action={action} className="space-y-4">
      <Banner state={state} okText="Domain added." />
      {brands.length === 0 && <p className="text-sm text-amber-300">Add a brand first — a domain belongs to a sending brand.</p>}
      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        <div>
          <label className="label">Brand</label>
          <select className="input" name="brandId" required defaultValue="">
            <option value="" disabled>
              Pick a brand…
            </option>
            {brands.map((b) => (
              <option key={b.id} value={b.id}>
                {b.label}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label className="label">Apex domain</label>
