/** Compact planned-ramp bar chart; highlights the current warmup day. */
function RampChart({ startCap, targetCap, rampDays, currentDay }: { startCap: number; targetCap: number; rampDays: number; currentDay: number }) {
  const curve = warmupRampCurve({ startCap, targetCap, rampDays });
  const max = Math.max(1, targetCap);
  return (
    <div className="flex h-16 items-end gap-[2px]">
      {curve.map((p) => {
        const h = Math.max(6, Math.round((p.planned / max) * 100));
        const isNow = p.day === Math.min(currentDay, rampDays);
        return (
          <div
            key={p.day}
            title={`Day ${p.day + 1}: ${p.planned}/day`}
            style={{ height: `${h}%` }}
            className={`w-full rounded-sm ${isNow ? "bg-brand-400" : p.day < currentDay ? "bg-brand-500/70" : "bg-white/10"}`}
          />
        );
      })}
    </div>
  );
}

