                    </p>
                  </div>
                  <Badge tone={mode.safe ? "green" : "amber"}>{mode.label}</Badge>
                </div>

                {!ib.warmupStartedAt ? (
                  <p className="text-sm text-slate-400">Warmup not started.</p>
                ) : (
                  <>
                    <p className="text-sm text-slate-300">{w.label}</p>
                    <RampChart startCap={ib.startCap} targetCap={ib.targetCap} rampDays={ib.rampDays} currentDay={day} />
                    <div className="grid grid-cols-3 gap-3 text-center">
                      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
                        <p className="text-xs text-slate-500">Today</p>
                        <p className="text-lg font-bold text-brand-300">{ib.currentRampCap}</p>
                      </div>
                      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
                        <p className="text-xs text-slate-500">Target</p>
                        <p className="text-lg font-bold text-slate-200">{ib.targetCap}</p>
                      </div>
                      <div className="rounded-lg border border-white/[0.06] bg-white/[0.02] p-2">
                        <p className="text-xs text-slate-500">Health</p>
                        <p className={`text-lg font-bold ${ib.healthScore >= 75 ? "text-emerald-300" : ib.healthScore >= 50 ? "text-amber-300" : "text-red-300"}`}>
                          {ib.healthScore}
                        </p>
                      </div>
                    </div>
                  </>
                )}
                {!mode.safe && <p className="text-xs text-amber-300/80">{mode.note}</p>}
                {ib.pausedReason && <p className="text-xs text-red-300">{ib.pausedReason}</p>}
                <InboxControls id={ib.id} status={ib.status} />
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import Link from "next/link";
import { db } from "@/lib/db";
import { requireArea } from "@/lib/rbac";
import { PageHeader, Badge, EmptyState } from "@/components/ui/primitives";
import { SeedTestForm, DeliverabilitySignalForm } from "@/components/admin/coldemail/Phase3Controls";
import {
  deriveRates,
  addCounts,
  ZERO_COUNTS,
  formatPct,
  bounceBand,
  complaintBand,
  placementBand,
  OPEN_RATE_WARNING,
  type MetricCounts,
  type Band,
} from "@/lib/coldemail/analytics";

export const dynamic = "force-dynamic";

const WINDOW_DAYS = 30;
const bandText: Record<Band, string> = { green: "text-emerald-300", amber: "text-amber-300", red: "text-red-300" };

function Tile({ label, value, band, hint }: { label: string; value: string; band?: Band; hint?: string }) {
  return (
    <div className="card p-4">
      <p className="text-[13px] text-slate-400">{label}</p>
      <p className={`mt-1 text-2xl font-bold ${band ? bandText[band] : "text-slate-100"}`}>{value}</p>
      {hint && <p className="mt-1 text-xs text-slate-500">{hint}</p>}
    </div>
  );
}

function sumRows(rows: { scopeId: string } & Partial<MetricCounts>[] | MetricCounts[]): MetricCounts {
  let acc = { ...ZERO_COUNTS };
  for (const r of rows as unknown as MetricCounts[]) acc = addCounts(acc, r);
  return acc;
}

export default async function ColdEmailAnalytics() {
  await requireArea("platform");

  const since = new Date(Date.now() - WINDOW_DAYS * 86_400_000);

  const [metrics, domains, inboxes, healthRows, placements] = await Promise.all([
    db.metricsDaily.findMany({ where: { date: { gte: since } } }),
    db.sendingDomain.findMany({ include: { brand: { select: { name: true } } } }),
    db.inbox.findMany({ include: { sendingDomain: { select: { domain: true, subdomain: true } } } }),
    db.healthSnapshot.findMany({ where: { date: { gte: since } }, orderBy: { date: "desc" } }),
    db.placementTest.findMany({ orderBy: { runAt: "desc" } }),
  ]);

  // Aggregate counts by scope+scopeId over the window.
  const agg = new Map<string, MetricCounts>();
  const overall = { ...ZERO_COUNTS } as MetricCounts;
  for (const m of metrics) {
    const key = `${m.scope}:${m.scopeId}`;
    agg.set(key, addCounts(agg.get(key) ?? ZERO_COUNTS, m as unknown as MetricCounts));
    if (m.scope === "CAMPAIGN") Object.assign(overall, addCounts(overall, m as unknown as MetricCounts));
  }
  const overallRates = deriveRates(overall);

  // Latest health snapshot + placement per scopeId.
  const latestHealth = new Map<string, (typeof healthRows)[number]>();
  for (const h of healthRows) if (!latestHealth.has(`${h.scope}:${h.scopeId}`)) latestHealth.set(`${h.scope}:${h.scopeId}`, h);
  const latestPlacement = new Map<string, (typeof placements)[number]>();
  for (const p of placements) if (!latestPlacement.has(p.sendingDomainId)) latestPlacement.set(p.sendingDomainId, p);

  const hasData = metrics.length > 0;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Deliverability analytics"
        sub="Reply, bounce, complaint, click and inbox-placement are the health signals. Open rate is shown but flagged — Apple MPP inflates it, so it is never an optimization target."
      />

      {/* Overview trends */}
      <div className="card">
        <div className="mb-4 flex items-center justify-between">
          <p className="section-label">Last {WINDOW_DAYS} days (all campaigns)</p>
          <Badge tone="slate">{overall.sent} sent</Badge>
        </div>
        {!hasData ? (
          <p className="text-sm text-slate-400">No deliverability events rolled up yet. Rollups populate once campaigns send (or you record manual signals below).</p>
        ) : (
          <div className="grid gap-3 sm:grid-cols-3 lg:grid-cols-4">
            <Tile label="Positive reply" value={formatPct(overallRates.positiveReplyRate)} band="green" hint="The 2026 hero metric." />
            <Tile label="Reply rate" value={formatPct(overallRates.replyRate)} band="green" />
            <Tile label="Delivery" value={formatPct(overallRates.deliveryRate)} />
            <Tile label="Bounce" value={formatPct(overallRates.bounceRate)} band={bounceBand(overallRates.bounceRate)} hint="<2% good · >5% stop" />
            <Tile label="Complaint" value={formatPct(overallRates.complaintRate, 3)} band={complaintBand(overallRates.complaintRate)} hint="0.3% hard ceiling" />
            <Tile label="Click" value={formatPct(overallRates.clickRate)} hint="MPP-resistant" />
            <Tile label="Unsubscribe" value={formatPct(overallRates.unsubRate)} />
            <Tile label="Open rate (unreliable)" value={formatPct(overallRates.openRate)} hint="⚠ MPP-inflated — do not optimize on this" />
          </div>
        )}
        <p className="mt-3 rounded-lg border border-amber-500/25 bg-amber-500/[0.06] px-3 py-2 text-xs text-amber-200/90">
          ⚠ {OPEN_RATE_WARNING}
        </p>
      </div>

      {/* Per-domain health */}
      <div className="card">
        <p className="section-label mb-4">Domain health</p>
        {domains.length === 0 ? (
          <EmptyState title="No domains" sub="Add sending domains under Domains & inboxes." />
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-xs uppercase tracking-wide text-slate-500">
                  <th className="py-2 pr-3">Domain</th>
                  <th className="py-2 pr-3">Status</th>
                  <th className="py-2 pr-3">Sent</th>
                  <th className="py-2 pr-3">Bounce</th>
                  <th className="py-2 pr-3">Complaint</th>
                  <th className="py-2 pr-3">Placement</th>
                  <th className="py-2 pr-3">Health</th>
                </tr>
              </thead>
              <tbody>
                {domains.map((d) => {
                  const c = agg.get(`DOMAIN:${d.id}`) ?? ZERO_COUNTS;
                  const r = deriveRates(c);
                  const h = latestHealth.get(`DOMAIN:${d.id}`);
                  const p = latestPlacement.get(d.id);
                  return (
                    <tr key={d.id} className="border-t border-white/[0.05]">
                      <td className="py-2 pr-3 font-medium text-white">
                        {d.subdomain}.{d.domain} <span className="text-xs text-slate-500">({d.brand.name})</span>
                      </td>
                      <td className="py-2 pr-3">
                        <Badge tone={d.status === "ACTIVE" || d.status === "WARMING" ? "green" : "red"}>{d.status.toLowerCase()}</Badge>
                      </td>
                      <td className="py-2 pr-3 text-slate-400">{c.sent}</td>
                      <td className={`py-2 pr-3 ${bandText[bounceBand(r.bounceRate)]}`}>{formatPct(r.bounceRate)}</td>
                      <td className={`py-2 pr-3 ${bandText[complaintBand(r.complaintRate)]}`}>{formatPct(r.complaintRate, 3)}</td>
                      <td className={`py-2 pr-3 ${p ? bandText[placementBand(p.inboxPct)] : "text-slate-500"}`}>
                        {p ? formatPct(p.inboxPct, 0) : "—"}
                      </td>
                      <td className="py-2 pr-3 text-slate-300">{h ? h.healthScore : "—"}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Per-inbox health */}
      <div className="card">
        <p className="section-label mb-4">Inbox health</p>
        {inboxes.length === 0 ? (
          <p className="text-sm text-slate-400">No inboxes yet.</p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="text-left text-xs uppercase tracking-wide text-slate-500">
                  <th className="py-2 pr-3">Mailbox</th>
                  <th className="py-2 pr-3">Status</th>
                  <th className="py-2 pr-3">Sent</th>
                  <th className="py-2 pr-3">Bounce</th>
                  <th className="py-2 pr-3">Reply</th>
                  <th className="py-2 pr-3">Health</th>
                </tr>
              </thead>
              <tbody>
                {inboxes.map((ib) => {
                  const c = agg.get(`INBOX:${ib.id}`) ?? ZERO_COUNTS;
                  const r = deriveRates(c);
                  const h = latestHealth.get(`INBOX:${ib.id}`);
                  return (
                    <tr key={ib.id} className="border-t border-white/[0.05]">
                      <td className="py-2 pr-3 font-medium text-white">{ib.email}</td>
                      <td className="py-2 pr-3">
                        <Badge tone={ib.status === "ACTIVE" ? "green" : ib.status === "WARMING" ? "amber" : "red"}>{ib.status.toLowerCase()}</Badge>
                      </td>
                      <td className="py-2 pr-3 text-slate-400">{c.sent}</td>
                      <td className={`py-2 pr-3 ${bandText[bounceBand(r.bounceRate)]}`}>{formatPct(r.bounceRate)}</td>
                      <td className="py-2 pr-3 text-emerald-300">{formatPct(r.replyRate)}</td>
                      <td className="py-2 pr-3 text-slate-300">{h ? h.healthScore : ib.healthScore}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <div className="grid gap-6 lg:grid-cols-2">
        <div className="card">
          <p className="section-label mb-4">Record an inbox-placement (seed) test</p>
          <SeedTestForm domains={domains.map((d) => ({ id: d.id, label: `${d.subdomain}.${d.domain}` }))} />
        </div>
        <div className="card">
          <p className="section-label mb-4">Record a deliverability signal</p>
          <DeliverabilitySignalForm />
        </div>
      </div>

      <p className="text-xs text-slate-500">
        Placement testing tools: <Link className="text-brand-300 hover:underline" href="https://www.mailreach.co/blog/email-spam-test-tools" target="_blank">MailReach</Link> ·{" "}
        <Link className="text-brand-300 hover:underline" href="https://mailflowauthority.com/esp-reviews/glockapps-review" target="_blank">GlockApps</Link>. Record their results here to chart inbox-vs-spam over time.
      </p>
    </div>
  );
}

